INSERT INTO `ai_evaluations` VALUES (1,8,NULL,'hanmant dhotre exhibits strong competency for System Administrator within Operations. Demonstrated structured problem-solving and solid aptitude across technical and role-specific assessments, alongside clear communication in preliminary evaluation.','[\"Demonstrated solid foundational grasp in Operations assessment (70% performance index).\",\"Articulate communication and professional etiquette observed throughout evaluation.\",\"Verified suitability for System Administrator operational responsibilities at Taraj Global Solutions.\"]','[\"Recommend further deep-dive verification on practical end-to-end task execution.\",\"Evaluate adaptation speed to Taraj Global Solutions internal workflow tooling.\"]','[\"Cross-verify practical screening solution nuance with department technical lead.\",\"Confirm availability and alignment with company onboarding timeline.\"]',7.00,7.20,7.50,7.20,'recommend','v1.0','HRMS-Synthesis-Engine-v2','completed','{\"synthesized\":true,\"score\":7.2}','2026-10-13 20:32:52','2026-10-13 20:32:52'),(2,3,NULL,'rahul sharma demonstrates dependable competence for the Business Development Executive role within Sales. Performance across multi-round technical evaluations highlights sound analytical problem-solving and structured methodology, paired with professional articulation in preliminary screening.','[\"Demonstrated solid foundational proficiency in Sales assessment (53% performance index).\",\"Articulate communication and professional etiquette observed throughout the evaluation workflow.\",\"Verified suitability for Business Development Executive operational responsibilities at Taraj Global Solutions.\"]','[\"Recommend further deep-dive verification on edge-case scenario handling.\",\"Evaluate adaptation speed to Taraj Global Solutions internal workflow tooling.\"]','[\"Cross-verify practical screening solution nuance with department technical lead.\",\"Confirm availability and alignment with company onboarding timeline.\"]',5.30,5.50,5.40,5.40,'neutral','v1.0','HRMS-Synthesis-Engine-v2','completed','{\"synthesized\":true,\"performanceIndex\":52.77777777777778,\"totalEvaluatedAnswers\":9}','2026-10-13 22:18:23','2026-10-13 22:18:23'),(3,12,NULL,'tejas pawar demonstrates dependable competence for the Business Development Executive role within Sales. Performance across multi-round technical evaluations highlights sound analytical problem-solving and structured methodology, paired with professional articulation in preliminary screening.','[\"Demonstrated solid foundational proficiency in Sales assessment (70% performance index).\",\"Articulate communication and professional etiquette observed throughout the evaluation workflow.\",\"Verified suitability for Business Development Executive operational responsibilities at Taraj Global Solutions.\"]','[\"Recommend further deep-dive verification on edge-case scenario handling.\",\"Evaluate adaptation speed to Taraj Global Solutions internal workflow tooling.\"]','[\"Cross-verify practical screening solution nuance with department technical lead.\",\"Confirm availability and alignment with company onboarding timeline.\"]',7.30,7.20,7.10,7.20,'recommend','v1.0','HRMS-Synthesis-Engine-v2','completed','{\"synthesized\":true,\"performanceIndex\":70,\"totalEvaluatedAnswers\":9}','2026-10-14 01:42:30','2026-10-14 01:42:30');
