--
-- Table structure for table `candidates`
--

DROP TABLE IF EXISTS `candidates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `candidates` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `candidate_code` varchar(30) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `email` varchar(120) NOT NULL,
  `phone` varchar(25) NOT NULL,
  `date_of_birth` date DEFAULT NULL,
  `address` text DEFAULT NULL,
  `candidate_type` enum('Fresher','Experienced') NOT NULL DEFAULT 'Experienced',
  `department_id` int(10) unsigned NOT NULL,
  `position_id` int(10) unsigned NOT NULL,
  `qualification` varchar(120) DEFAULT NULL,
  `college_or_institution` varchar(150) DEFAULT NULL,
  `graduation_year` int(10) unsigned DEFAULT NULL,
  `experience_years` decimal(4,1) NOT NULL DEFAULT 0.0,
  `current_employer` varchar(120) DEFAULT NULL,
  `current_ctc` varchar(60) DEFAULT NULL,
  `expected_ctc` varchar(60) DEFAULT NULL,
  `notice_period` int(10) unsigned DEFAULT 0,
  `resume_file_path` varchar(500) DEFAULT NULL,
  `resume_original_name` varchar(255) DEFAULT NULL,
  `application_status` enum('registered','hr_interview','dept_interview','final_screening','evaluation','offered','rejected','on_hold','joined') NOT NULL DEFAULT 'registered',
  `registration_source` varchar(50) NOT NULL DEFAULT 'qr_code',
  `qr_token` varchar(64) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `registered_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `candidate_code` (`candidate_code`),
  UNIQUE KEY `qr_token` (`qr_token`),
  KEY `idx_cand_status` (`application_status`),
  KEY `idx_cand_dept` (`department_id`),
  KEY `idx_cand_pos` (`position_id`),
  KEY `idx_cand_code` (`candidate_code`),
  KEY `idx_cand_email` (`email`),
  KEY `idx_cand_phone` (`phone`),
  CONSTRAINT `candidates_ibfk_1` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `candidates_ibfk_2` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `candidates`
--

LOCK TABLES `candidates` WRITE;
/*!40000 ALTER TABLE `candidates` DISABLE KEYS */;
