--
-- Table structure for table `interview_answers`
--

DROP TABLE IF EXISTS `interview_answers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `interview_answers` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `interview_id` int(10) unsigned NOT NULL,
  `question_id` int(10) unsigned NOT NULL,
  `question_text_snapshot` text NOT NULL,
  `answer_text` text DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `answered_at` datetime DEFAULT NULL,
  `duration_seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `score` decimal(4,2) NOT NULL DEFAULT 0.00,
  `maximum_score` int(10) unsigned NOT NULL DEFAULT 10,
  `interviewer_remarks` text DEFAULT NULL,
  `evaluation_status` enum('pending','evaluated') NOT NULL DEFAULT 'evaluated',
  `recording_url` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_interview_quest` (`interview_id`,`question_id`),
  KEY `question_id` (`question_id`),
  KEY `idx_ans_interview` (`interview_id`),
  CONSTRAINT `interview_answers_ibfk_1` FOREIGN KEY (`interview_id`) REFERENCES `interviews` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `interview_answers_ibfk_2` FOREIGN KEY (`question_id`) REFERENCES `interview_questions` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=199 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

