LOCK TABLES `interview_questions` WRITE;
/*!40000 ALTER TABLE `interview_questions` DISABLE KEYS */;
INSERT INTO `interview_questions` VALUES (1,NULL,NULL,NULL,1,'hr','Tell us about yourself, your educational background, and what motivated you to apply for this role?','hr_easy',NULL,NULL,10,'Clear self-introduction, relevant educational background, positive attitude, and motivation for the role.',120,1.00,0,'2026-10-09 19:30:12','2026-10-14 20:52:38'),(2,NULL,NULL,NULL,1,'hr','What do you consider your greatest personal or professional strengths, and how do you like to work within a team?','hr_easy',NULL,NULL,10,'Self-awareness of strengths, collaboration, active listening, and supporting colleagues.',120,1.00,0,'2026-10-09 19:30:12','2026-10-14 20:52:38'),(3,NULL,NULL,NULL,1,'hr','How do you handle working with tight deadlines, and how do you communicate when you need help or clarification?','hr_easy',NULL,NULL,10,'Time management, prioritizing tasks, proactive communication with leads and peers.',120,1.00,0,'2026-10-09 19:30:12','2026-10-14 20:52:38'),(4,NULL,NULL,NULL,3,'hr','What do you know about Taraj Global Solutions, and what kind of IT, digital, or business solutions do we provide?','company',NULL,NULL,10,'Knowledge of Taraj Global Solutions, B2B services, IT consulting, recruitment solutions, and client growth focus.',120,1.00,0,'2026-10-09 19:30:12','2026-10-14 20:52:38'),(5,2,NULL,NULL,2,'department','Can you explain the difference between frontend and backend in a modern web application?','technical',NULL,NULL,10,'Frontend handles user interface, design, and user interactions; Backend handles database, APIs, authentication, and server logic.',180,1.25,0,'2026-10-09 19:30:12','2026-10-22 19:57:25'),(6,2,NULL,NULL,2,'department','What are RESTful APIs, and what is the difference between a GET and a POST request?','technical',NULL,NULL,10,'REST APIs communicate over HTTP methods; GET fetches data without modifying state; POST sends payload to create or process data.',180,1.25,0,'2026-10-09 19:30:12','2026-10-22 19:57:25'),(7,2,NULL,NULL,2,'department','How do you use Git version control in your day-to-day work for creating branches, committing changes, and pushing code?','technical',NULL,NULL,10,'git checkout -b branch-name, git add, git commit with meaningful message, git push, and pull request review.',180,1.25,0,'2026-10-09 19:30:12','2026-10-22 19:57:25'),(8,1,NULL,NULL,2,'department','What is the difference between Manual Testing and Automated Testing, and when should you use each?','technical',NULL,NULL,10,'Manual for exploratory, ad-hoc and UI usability testing; Automated for repetitive regression and continuous integration suites.',180,1.25,0,'2026-10-09 19:30:12','2026-10-15 00:08:59'),(9,1,NULL,NULL,2,'department','Can you explain what a Test Case is and what key information every good test case should contain?','technical',NULL,NULL,10,'Test Case ID, Title, Preconditions, Step-by-step instructions, Test Data, Expected Result, and Actual Result.',180,1.25,0,'2026-10-09 19:30:12','2026-10-15 00:08:59'),(10,7,NULL,NULL,2,'department','What is a Primary Key and a Foreign Key in a relational database like MySQL, and why are they important?','technical',NULL,NULL,10,'Primary key uniquely identifies each table record; Foreign key establishes relationship between tables and prevents orphan rows.',180,1.25,0,'2026-10-09 19:30:12','2026-10-22 20:29:21'),(11,2,NULL,NULL,5,'final','Practical Task 1: Write a simple SQL query to retrieve the full name and email of all candidates who applied for the \"Development\" department and have status \"new\".','practical',NULL,NULL,10,'SELECT full_name, email FROM candidates WHERE department_id = 2 AND status = \'new\';',240,1.50,1,'2026-10-09 19:30:12','2026-10-09 21:41:47'),(12,2,NULL,NULL,5,'final','Practical Task 2: Write a short JavaScript function isValidEmail(email) that returns true if the email string contains \"@\" and \".\", and false otherwise.','practical',NULL,NULL,10,'function isValidEmail(email) { return email && email.includes(\"@\") && email.includes(\".\"); }',240,1.50,1,'2026-10-09 19:30:12','2026-10-09 21:41:47'),(13,2,NULL,NULL,5,'final','Practical Task 3: In a React component, explain how you would show a \"Loading...\" indicator while fetching candidate data from an API, and display the candidate list once loaded.','practical',NULL,NULL,10,'Define useState for loading (true/false) and candidates (array); fetch in useEffect on mount; conditionally render spinner or candidates list.',240,1.50,1,'2026-10-09 19:30:12','2026-10-09 21:41:47'),(14,NULL,NULL,NULL,3,'hr','Why do you want to work specifically at Taraj Global Solutions, and how do you see our company culture fitting your career goals?','company',NULL,NULL,10,'Genuine enthusiasm for Taraj Global Solutions, alignment with company values, eagerness to learn and grow.',120,1.00,0,'2026-10-09 20:27:08','2026-10-14 20:52:38'),(15,4,NULL,NULL,2,'department','What is the difference between Inbound leads and Outbound leads in sales?','technical',NULL,NULL,10,'Inbound leads discover the company through content/website and reach out; Outbound leads are contacted directly via cold outreach.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:08:12'),(16,4,NULL,NULL,2,'department','How do you research a prospective company or client before picking up the phone or sending a cold outreach message?','technical',NULL,NULL,10,'Review LinkedIn profile, company website, recent news, industry challenges, identifying key decision-maker titles.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:08:12'),(17,4,NULL,NULL,2,'department','When a prospect says \"We are not interested right now\", how do you politely respond to understand their reasoning and keep the door open?','situational',NULL,NULL,10,'Acknowledge gracefully, ask polite question about current workflow or timeline, ask permission to share a case study for future.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:08:12'),(18,4,18,NULL,2,'department','How do you apply the BANT qualification framework (Budget, Authority, Need, Timeline) during prospect discovery?','situational',NULL,NULL,10,'Uncovering real budget allocation, mapping buying committee authority, verifying pressing business pain, timeline urgency.',180,1.50,0,'2026-10-09 20:27:08','2026-10-09 21:41:47'),(19,4,18,NULL,2,'department','Describe your approach to designing and executing an Account-Based Marketing (ABM) campaign for high-value enterprise accounts.','technical',NULL,NULL,10,'Tiered account selection, personalized multi-channel touchpoints (content syndication, LinkedIn, email), sales alignment.',240,1.50,0,'2026-10-09 20:27:08','2026-10-09 21:41:47'),(20,4,NULL,NULL,2,'department','What essential information do you record in a CRM (like HubSpot or Salesforce) to ensure smooth sales follow-ups?','technical',NULL,NULL,10,'Prospect name, company, pain points discussed, agreed next action, follow-up date, deal stage, and decision-maker roles.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:08:12'),(21,8,NULL,NULL,2,'department','What are the key metrics used to measure the success of an email marketing campaign (Open Rate, Click Rate, Unsubscribe Rate)?','technical',NULL,NULL,10,'Open rate reflects subject line interest; Click rate reflects engagement and offer appeal; Unsubscribe/bounce shows list health.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:34:37'),(22,8,NULL,NULL,2,'department','What best practices do you follow to ensure marketing emails don\'t end up in the spam folder?','technical',NULL,NULL,10,'Verify SPF, DKIM, DMARC records, maintain clean opted-in email lists, avoid spam trigger words, include clear unsubscribe link.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:34:37'),(23,8,NULL,NULL,2,'department','How do you segment an email subscriber list to send more relevant messages to different audiences?','technical',NULL,NULL,10,'Segment by engagement level, buyer personas, industry, previous purchase/download behavior to improve relevance.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:34:37'),(24,7,NULL,NULL,2,'department','What is the difference between WHERE and HAVING clauses in an SQL query?','technical',NULL,NULL,10,'WHERE filters rows before grouping; HAVING filters summary rows after GROUP BY aggregation.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:29:21'),(25,3,NULL,NULL,4,'department','What is the difference between Agile and traditional Waterfall project management methodologies?','situational',NULL,NULL,10,'Agile uses flexible, short sprints and continuous collaboration; Waterfall follows linear, rigid phases from requirements to delivery.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:03:03'),(26,3,NULL,NULL,4,'department','How do you track daily project progress and ensure team members meet their sprint deliverables without feeling micromanaged?','situational',NULL,NULL,10,'Short daily standups, clear Kanban/Scrum board updates, transparent sprint goals, removing roadblocks quickly.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:03:03'),(27,6,NULL,NULL,2,'department','What are the common daily responsibilities of an operations team in an IT company?','technical',NULL,NULL,10,'Facilities management, workstation and IT asset management, vendor coordination, procurement, process adherence.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:23:38'),(28,6,NULL,NULL,4,'department','If an office network or workstation suddenly stops connecting to the internet, what basic troubleshooting steps do you take?','situational',NULL,NULL,10,'Check ethernet cables/Wi-Fi switch, ping default gateway, check DNS settings, restart network adapter or router.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:23:38'),(29,5,NULL,NULL,1,'department','What key steps do you follow when sourcing and screening resumes for an open job requirement?','technical',NULL,NULL,10,'Analyze job description criteria, review relevant work experience, check technical/soft skills fit, evaluate resume clarity.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:18:18'),(30,5,NULL,NULL,4,'department','How do you coordinate with department managers to understand what skills they are looking for in a new hire?','situational',NULL,NULL,10,'Conduct recruitment intake meeting, align on required vs preferred skills, set realistic salary/experience benchmarks.',180,1.25,0,'2026-10-09 20:27:08','2026-10-22 20:18:18'),(31,1,NULL,NULL,2,'department','When you discover a bug in an application, what steps do you take to verify and report it clearly to the developers?','technical',NULL,NULL,10,'Reproduce bug reliably, isolate variables, capture logs/screenshots, write clear steps to reproduce in bug tracker.',180,1.25,0,'2026-10-09 21:41:47','2026-10-15 00:08:59'),(32,2,NULL,NULL,2,'department','How do you approach debugging when a web page throws an unexpected error in the browser or terminal console?','technical',NULL,NULL,10,'Inspect console stack trace, check network tab requests/responses, review recent code diffs, verify state variables.',180,1.25,0,'2026-10-09 21:41:47','2026-10-22 19:57:25'),(33,3,NULL,NULL,4,'department','How do you communicate with clients or stakeholders when a feature delivery might take longer than originally planned?','situational',NULL,NULL,10,'Proactive early communication, explaining root cause honestly, presenting realistic revised dates and solutions.',180,1.25,0,'2026-10-09 21:41:47','2026-10-22 20:03:03'),(34,5,NULL,NULL,3,'department','What makes a welcoming first-day onboarding experience for a new employee joining the company?','situational',NULL,NULL,10,'Prepared workstation, designated onboarding buddy, clear first-day agenda, warm team introduction, and HR orientation.',180,1.25,0,'2026-10-09 21:41:47','2026-10-22 20:18:18'),(35,6,NULL,NULL,2,'department','How do you keep track of office IT assets (laptops, monitors, credentials) and vendor supplies?','technical',NULL,NULL,10,'Asset inventory tracking sheet, serial numbers, allocation logs, checkout agreements, scheduled physical audits.',180,1.25,0,'2026-10-09 21:41:47','2026-10-22 20:23:38'),(36,7,NULL,NULL,2,'department','Why are regular database backups essential, and what is the difference between full and incremental backups?','technical',NULL,NULL,10,'Disaster recovery and business continuity; Full backup copies all data; Incremental copies only data modified since last backup.',180,1.25,0,'2026-10-09 21:41:47','2026-10-22 20:29:21'),(37,2,NULL,NULL,5,'final','Practical Task 4: An API endpoint returns HTTP 500 error when submitting an interview score. What are the 3 immediate steps you take to trace and fix the issue?','practical',NULL,NULL,10,'1. Check terminal/server console for crash error stack, 2. Inspect request payload in network tab, 3. Validate SQL parameters and database columns.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(38,2,NULL,NULL,5,'final','Practical Task 5: Write the Git commands to create a new branch called \"feature/candidate-notes\", commit your changes with a message, and push it to GitHub.','practical',NULL,NULL,10,'git checkout -b feature/candidate-notes; git add .; git commit -m \"Add candidate notes feature\"; git push -u origin feature/candidate-notes;',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(41,1,NULL,NULL,5,'final','Practical Task 1: Write 3 simple test cases for a candidate registration form (Fields: Full Name, Email, Phone Number). Include 1 positive case and 2 negative validation cases.','practical',NULL,NULL,10,'Positive case with all valid values; Negative 1 with invalid email syntax; Negative 2 with empty phone or required field missing.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(42,1,NULL,NULL,5,'final','Practical Task 2: A candidate clicks \"Submit Application\" but nothing happens and no message appears. Write a clear bug report with Title, Steps to Reproduce, Expected Result, and Actual Result.','practical',NULL,NULL,10,'Clear title, numbered steps to reproduce, expected submission success or error message, actual silent failure.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(43,1,NULL,NULL,5,'final','Practical Task 3: Test an age input field where the allowed age is between 18 and 60. List the specific boundary values you will test to verify validation rules.','practical',NULL,NULL,10,'Boundary values: 17 (just below min - invalid), 18 (min - valid), 19 (valid), 59 (valid), 60 (max - valid), 61 (just above max - invalid).',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(44,1,NULL,NULL,5,'final','Practical Task 4: Review a simple user login screen with a \"Remember Me\" checkbox. List 4 quick functional checks you would perform before approving the build for release.','practical',NULL,NULL,10,'1. Valid login credentials, 2. Invalid password error, 3. Blank fields validation, 4. Remember Me cookie/session persistence on browser restart.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(45,1,NULL,NULL,5,'final','Practical Task 5: A developer fixed a reported bug in the candidate search filter. Explain what regression testing checks you will perform to confirm no other feature was broken.','practical',NULL,NULL,10,'Verify the bug fix itself, test other department filters, test pagination, check search reset button, check mobile responsiveness.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(51,3,NULL,NULL,5,'final','Practical Task 1: You need to deliver a new \"QR Code Onboarding\" feature in a 2-week sprint. Break down this feature into 3 clear, manageable user stories or tasks.','practical',NULL,NULL,10,'1. Generate and display QR code on portal, 2. Mobile registration form for candidates, 3. Secure backend submission and database entry.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(52,3,NULL,NULL,5,'final','Practical Task 2: A developer informs you on Thursday afternoon that a key deliverable promised for Friday will be delayed by 2 days. Draft a short, professional update note to the stakeholder.','practical',NULL,NULL,10,'Polite tone, transparent reason for delay, realistic revised date (Monday), highlighting thorough testing to preserve quality.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(53,3,NULL,NULL,5,'final','Practical Task 3: You have 3 urgent items: (A) A typo on the website homepage, (B) A bug preventing candidates from submitting applications, (C) Sprint planning for next month. Order them 1 to 3 by priority and briefly explain why.','practical',NULL,NULL,10,'Priority 1: B (business blocking), Priority 2: A (quick public-facing fix), Priority 3: C (strategic planning done after unblocking users).',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(54,3,NULL,NULL,5,'final','Practical Task 4: Design a clean 15-minute daily standup agenda for a team of 6 engineers to keep everyone aligned without running over time.','practical',NULL,NULL,10,'Round-robin format: What did I complete yesterday? What am I working on today? Any blockers? Strict 2 minutes per person with parking lot for deeper discussions.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(55,3,NULL,NULL,5,'final','Practical Task 5: The sprint just concluded. Write 2 specific questions you would ask the team in a retrospective meeting to help improve the next sprint.','practical',NULL,NULL,10,'1. What went exceptionally well that we should repeat? 2. What slowed us down or could be streamlined in our workflow?',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(61,4,NULL,NULL,5,'final','Practical Task 1: Draft a short, professional 3-sentence introductory email to an HR Director offering a 15-minute demonstration of Taraj Global Solutions\' recruitment software.','practical',NULL,NULL,10,'Sentence 1: Personalized hook on automating hiring workflows. Sentence 2: Core value of 3-round assessments and QR onboarding. Sentence 3: Low-friction call to action for a 15-minute demo.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(62,4,NULL,NULL,5,'final','Practical Task 2: During a discovery call, a prospect says: \"We currently manage all recruitment in Excel sheets and it works fine for us.\" Write a polite response highlighting the benefits of upgrading.','practical',NULL,NULL,10,'Acknowledge spreadsheet ease, point out risks of lost candidate records, emphasize automated QR code registration, scorecards, and time savings.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(63,4,NULL,NULL,5,'final','Practical Task 3: If you make 50 cold calls per day, 10 prospects agree to receive company details, and 2 book a qualified product demo, calculate your conversion rate from calls to booked demos.','practical',NULL,NULL,10,'(2 booked demos / 50 total calls) * 100 = 4.0% conversion rate.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(64,4,NULL,NULL,5,'final','Practical Task 4: A prospect agreed to a demo but has not accepted the calendar invite after 48 hours. Write a friendly, 2-sentence follow-up message.','practical',NULL,NULL,10,'Friendly reminder with meeting time, offering flexibility to reschedule if original time no longer works.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(65,4,NULL,NULL,5,'final','Practical Task 5: List the 4 key qualifying details (BANT or checklist) you must collect from a lead before passing them over to an Account Executive.','practical',NULL,NULL,10,'Budget indication, Authority/Decision maker identity, business Need/pain point, and expected Timeline for rollout.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(71,5,NULL,NULL,5,'final','Practical Task 1: Draft a friendly and professional email invitation to a candidate who passed Round 1, confirming the date, time, and link for Round 2: Department Interview.','practical',NULL,NULL,10,'Warm congratulatory opening, interview date & time, interviewer title, interview link/location, invitation to ask any questions.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(72,5,NULL,NULL,5,'final','Practical Task 2: A selected candidate is offered $50,000/year but requests $55,000. How do you handle this response professionally while consulting internal leadership?','practical',NULL,NULL,10,'Express gratitude for transparency, validate their interest, state you will review budget with hiring managers, set clear timeline for response.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(73,5,NULL,NULL,5,'final','Practical Task 3: Create a simple 5-step checklist for a new employee\'s Day 1 to ensure they feel welcomed and properly onboarded.','practical',NULL,NULL,10,'1. Welcome desk & badge, 2. IT login/laptop handoff, 3. Team introduction & buddy lunch, 4. HR policies overview, 5. Manager 1-on-1 expectations sync.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(74,5,NULL,NULL,5,'final','Practical Task 4: Two candidates have identical interview scores: Candidate A has stronger communication skills, while Candidate B has 1 extra year of experience. What factors would you consider to make a recommendation?','practical',NULL,NULL,10,'Examine team balance, communication requirement of the role, cultural adaptability, long-term learning agility.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(75,5,NULL,NULL,5,'final','Practical Task 5: An interviewer has not submitted their evaluation remarks 24 hours after an interview ended. Draft a polite, professional reminder note.','practical',NULL,NULL,10,'Polite greeting, mention candidate name and round, stress timely feedback for candidate experience, provide direct link to scorecard.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(81,6,NULL,NULL,5,'final','Practical Task 1: Create an IT onboarding checklist of 5 physical and digital items that must be prepared before a new employee arrives on their first day.','practical',NULL,NULL,10,'1. Configured laptop/OS, 2. Corporate email & chat credentials, 3. Office security access card, 4. Peripheral hardware (mouse/headset), 5. Wi-Fi connection profile.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(82,6,NULL,NULL,5,'final','Practical Task 2: An employee reports that their office laptop cannot connect to the Wi-Fi network, but other devices connect fine. List 3 basic troubleshooting steps to guide them through.','practical',NULL,NULL,10,'1. Turn Wi-Fi switch off and on, 2. Forget network and re-type password, 3. Restart device network adapter or run Windows network troubleshooter.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(83,6,NULL,NULL,5,'final','Practical Task 3: The office main internet connection goes down during working hours. Write a concise, reassuring message to notify staff and state when the next update will occur.','practical',NULL,NULL,10,'Clear statement of ISP outage, fallback procedure (mobile hotspot/local work), reassurance that ISP ticket is open, update promised within 30 minutes.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(84,6,NULL,NULL,5,'final','Practical Task 4: Outline a simple weekly checklist to verify that automated database backups are completing successfully and not running out of disk space.','practical',NULL,NULL,10,'1. Check backup timestamp log, 2. Verify non-zero file size, 3. Check disk storage capacity, 4. Confirm backup retention pruning ran correctly.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(85,6,NULL,NULL,5,'final','Practical Task 5: You need to purchase 5 new keyboards and mice for the office. What 3 steps do you take to compare vendor quotes and obtain purchase approval?','practical',NULL,NULL,10,'1. Request quotes from 2-3 approved suppliers, 2. Compare price, warranty, delivery speed, 3. Submit PO summary for manager sign-off.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(91,7,NULL,NULL,5,'final','Practical Task 1: Write an SQL query to find the total number of candidates in each department, displaying the department name and total candidate count.','practical',NULL,NULL,10,'SELECT d.name, COUNT(c.id) AS total_candidates FROM departments d LEFT JOIN candidates c ON d.id = c.department_id GROUP BY d.name;',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(92,7,NULL,NULL,5,'final','Practical Task 2: Candidate with ID 105 has an updated phone number \"9876543210\" and status \"interview_scheduled\". Write the SQL UPDATE statement to save these changes.','practical',NULL,NULL,10,'UPDATE candidates SET phone = \'9876543210\', status = \'interview_scheduled\' WHERE id = 105;',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(93,7,NULL,NULL,5,'final','Practical Task 3: A query \"SELECT * FROM candidates WHERE email = ?\" is running slowly on a table with 100,000 rows. What SQL command do you write to add an index on the email column?','practical',NULL,NULL,10,'CREATE INDEX idx_candidates_email ON candidates(email); or ALTER TABLE candidates ADD INDEX (email);',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(94,7,NULL,NULL,5,'final','Practical Task 4: Explain the difference between \"DELETE FROM candidates WHERE id = 5;\" and \"TRUNCATE TABLE candidates;\" in terms of data safety and ability to rollback.','practical',NULL,NULL,10,'DELETE removes specific rows, can be rolled back in a transaction, maintains autoincrement counter; TRUNCATE empties whole table, is DDL, cannot easily rollback, resets counter.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(95,7,NULL,NULL,5,'final','Practical Task 5: Write an SQL query that retrieves the candidate\'s full name, email, and position title by joining the candidates table with the positions table on position_id.','practical',NULL,NULL,10,'SELECT c.full_name, c.email, p.title FROM candidates c JOIN positions p ON c.position_id = p.id;',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(101,8,NULL,NULL,5,'final','Practical Task 1: Write 2 different email subject lines for a new product announcement: one focusing on curiosity/benefit and the other focusing on urgency/time.','practical',NULL,NULL,10,'Curiosity: \"How top teams cut hiring time by 50% 🚀\"; Urgency: \"Only 24 hours left: Early access pricing ends tonight ⏳\"',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(102,8,NULL,NULL,5,'final','Practical Task 2: If an email was sent to 5,000 subscribers, 1,000 opened the email, and 150 clicked a link inside, calculate the Open Rate percentage and Click-Through Rate (CTR) percentage.','practical',NULL,NULL,10,'Open Rate = (1,000 / 5,000) * 100 = 20.0%; CTR = (150 / 5,000) * 100 = 3.0% (Click-to-Open Rate = 15.0%).',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(103,8,NULL,NULL,5,'final','Practical Task 3: You notice that email deliverability suddenly dropped and open rates decreased. List 3 quick checks you will perform (sender reputation, spam words, subscriber list quality).','practical',NULL,NULL,10,'1. Check DNS records (SPF/DKIM/DMARC), 2. Check blacklist monitors/sender domain score, 3. Inspect email copy for spam triggers, 4. Prune unengaged subscribers.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(104,8,NULL,NULL,5,'final','Practical Task 4: Outline a 3-email welcome drip sequence for new subscribers (Email 1: Welcome & gift/intro, Email 2: Value & best resources, Email 3: Community invite / call to action).','practical',NULL,NULL,10,'Email 1 (Day 0): Welcome and instant resource delivery. Email 2 (Day 2): Case study and helpful tips. Email 3 (Day 4): Book a personal software walkthrough.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(105,8,NULL,NULL,5,'final','Practical Task 5: Explain the difference between a Hard Bounce and a Soft Bounce in email marketing, and what action should be taken immediately for hard bounces.','practical',NULL,NULL,10,'Hard bounce is a permanent error (invalid address/domain) and must be immediately removed; Soft bounce is temporary (mailbox full/server down) and can be retried.',240,1.50,1,'2026-10-09 21:41:47','2026-10-09 21:41:47'),(201,NULL,NULL,NULL,1,'hr','Tell me about yourself and explain the skills or experiences that make you suitable for this role.','hr',NULL,NULL,10,'Section A: HR Question. Evaluate communication clarity, relevant educational/professional background, personal strengths, and suitability for the role.',180,1.00,1,'2026-10-14 20:52:38','2026-10-17 02:29:34'),(202,NULL,NULL,NULL,1,'hr','Why do you want to join our company, and what do you know about our B2B business?','hr',NULL,NULL,10,'Section A: HR Question. Evaluate company research, understanding of B2B business model, motivation to work at Taraj Global Solutions, and organizational fit.',180,1.00,1,'2026-10-14 20:52:38','2026-10-17 02:29:34'),(203,NULL,NULL,NULL,1,'hr','What are your strengths and weaknesses, and how are you working to improve yourself?','hr',NULL,NULL,10,'Section A: HR Question. Evaluate self-awareness, authentic strengths with real examples, self-critique maturity, and active personal development steps.',180,1.00,1,'2026-10-14 20:52:38','2026-10-17 02:29:34'),(204,NULL,NULL,NULL,1,'hr','How do you handle constructive feedback from your manager or senior team members?','hr',NULL,NULL,10,'Section A: HR Question. Evaluate emotional maturity, coachability, positive attitude towards feedback, and willingness to adapt and improve.',180,1.00,1,'2026-10-14 20:52:38','2026-10-17 02:29:34'),(205,NULL,NULL,NULL,1,'hr','Why should we hire you for this position, and what value can you contribute to our team?','hr',NULL,NULL,10,'Section A: HR Question. Evaluate candidate value proposition, enthusiasm, understanding of deliverables, and team commitment.',180,1.00,1,'2026-10-14 20:52:38','2026-10-17 02:29:34'),(206,NULL,NULL,NULL,1,'hr','You have an important task due today, but an unexpected problem may prevent you from completing it on time. What would you do?','scenario',NULL,NULL,10,'Section B: Scenario-Based Question. Evaluate: (1) Problem identification & impact assessment, (2) Prompt and transparent communication with manager, (3) Proactive proposed mitigation or revised delivery schedule.',240,1.00,1,'2026-10-14 20:52:38','2026-10-17 04:11:24'),(207,NULL,NULL,NULL,3,'hr','You and your teammate disagree about how to complete a task. Both of you believe your approach is correct. How would you resolve the situation?','scenario',NULL,NULL,10,'Section B: Scenario-Based Question. Evaluate: (1) Active, respectful listening, (2) Objective comparison using facts and company goals, (3) Compromise or involving a lead/manager constructively.',240,1.00,1,'2026-10-14 20:52:38','2026-10-17 04:11:24'),(208,NULL,NULL,NULL,1,'hr','Your manager assigns you three tasks, and all have urgent deadlines. How would you prioritize and complete them?','scenario',NULL,NULL,10,'Section B: Scenario-Based Question. Evaluate: (1) Urgency vs impact matrix, (2) Seeking manager alignment on priorities, (3) Time-boxing, execution focus, and proactive progress updates.',240,1.00,1,'2026-10-14 20:52:38','2026-10-17 04:11:24'),(209,NULL,NULL,NULL,1,'hr','You discover that you submitted incorrect information that could affect your team or a client. What steps would you take?','scenario',NULL,NULL,10,'Section B: Scenario-Based Question. Evaluate: (1) Honesty and immediate disclosure, (2) Accountability without blame-shifting, (3) Rectifying the data/impact, and (4) Establishing safeguards against recurrence.',240,1.00,1,'2026-10-14 20:52:38','2026-10-17 04:11:24'),(210,NULL,NULL,NULL,1,'hr','Your manager assigns you a task you have never done before and is temporarily unavailable. How would you approach it?','scenario',NULL,NULL,10,'Section B: Scenario-Based Question. Evaluate: (1) Independent research and reviewing documentation, (2) Consulting knowledgeable peers or guidelines, (3) Preparing draft/framework, and (4) Validating with manager upon return.',240,1.00,1,'2026-10-14 20:52:38','2026-10-17 04:11:24'),(301,1,NULL,NULL,5,'department','What is the primary purpose of quality assurance in a business process?','mcq',NULL,NULL,1,'{\"title\":\"Q1. Primary Purpose of Quality Assurance\",\"section\":\"1\",\"section_title\":\"Section 1 — MCQ\",\"options\":[{\"key\":\"A\",\"text\":\"To increase the number of employees\"},{\"key\":\"B\",\"text\":\"To ensure processes and deliverables meet defined quality standards\"},{\"key\":\"C\",\"text\":\"To complete tasks without checking the results\"},{\"key\":\"D\",\"text\":\"To focus only on reducing employee costs\"}],\"correct_answer\":\"B\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: B. To ensure processes and deliverables meet defined quality standards\"}',120,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(302,1,NULL,NULL,5,'department','You find incorrect information in a report before it is shared with a client. What should you do?','mcq',NULL,NULL,1,'{\"title\":\"Q2. Handling Report Errors Before Client Sharing\",\"section\":\"1\",\"section_title\":\"Section 1 — MCQ\",\"options\":[{\"key\":\"A\",\"text\":\"Ignore the error if it looks minor\"},{\"key\":\"B\",\"text\":\"Share the report and correct it later\"},{\"key\":\"C\",\"text\":\"Verify the information, correct the error, and follow the appropriate reporting process\"},{\"key\":\"D\",\"text\":\"Delete the entire report without informing anyone\"}],\"correct_answer\":\"C\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: C. Verify the information, correct the error, and follow the appropriate reporting process\"}',120,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(303,1,NULL,NULL,5,'department','What is the main purpose of a Standard Operating Procedure (SOP)?','mcq',NULL,NULL,1,'{\"title\":\"Q3. Purpose of Standard Operating Procedure\",\"section\":\"1\",\"section_title\":\"Section 1 — MCQ\",\"options\":[{\"key\":\"A\",\"text\":\"To document consistent steps for carrying out a process\"},{\"key\":\"B\",\"text\":\"To replace all employee training\"},{\"key\":\"C\",\"text\":\"To record only employee attendance\"},{\"key\":\"D\",\"text\":\"To avoid measuring performance\"}],\"correct_answer\":\"A\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: A. To document consistent steps for carrying out a process\"}',120,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(304,1,NULL,NULL,5,'department','What does root-cause analysis help a quality team do?','mcq',NULL,NULL,1,'{\"title\":\"Q4. Purpose of Root-Cause Analysis\",\"section\":\"1\",\"section_title\":\"Section 1 — MCQ\",\"options\":[{\"key\":\"A\",\"text\":\"Identify who to blame for every mistake\"},{\"key\":\"B\",\"text\":\"Identify the underlying reason a problem occurred\"},{\"key\":\"C\",\"text\":\"Avoid documenting recurring problems\"},{\"key\":\"D\",\"text\":\"Finish an investigation without collecting evidence\"}],\"correct_answer\":\"B\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: B. Identify the underlying reason a problem occurred\"}',120,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(305,1,NULL,NULL,5,'department','Which of the following is the best example of a quality metric?','mcq',NULL,NULL,1,'{\"title\":\"Q5. Quality Metric Example\",\"section\":\"1\",\"section_title\":\"Section 1 — MCQ\",\"options\":[{\"key\":\"A\",\"text\":\"Number of office decorations\"},{\"key\":\"B\",\"text\":\"Employee favourite colour\"},{\"key\":\"C\",\"text\":\"Number of social events held\"},{\"key\":\"D\",\"text\":\"Error rate in completed work\"}],\"correct_answer\":\"D\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: D. Error rate in completed work\"}',120,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(306,1,NULL,NULL,5,'department','Which activities help maintain quality in a business process? Select all correct answers.','multiple_select',NULL,NULL,1,'{\"title\":\"Q6. Activities to Maintain Quality\",\"section\":\"2\",\"section_title\":\"Section 2 — Multiple Select\",\"options\":[{\"key\":\"A\",\"text\":\"Reviewing work against defined standards\"},{\"key\":\"B\",\"text\":\"Recording and tracking errors\"},{\"key\":\"C\",\"text\":\"Ignoring repeated defects\"},{\"key\":\"D\",\"text\":\"Taking corrective action when problems are identified\"}],\"correct_answer\":null,\"correct_answers\":[\"A\",\"B\",\"D\"],\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answers: A, B, D. Reviewing work against defined standards; Recording and tracking errors; Taking corrective action when problems are identified\"}',180,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(307,1,NULL,NULL,5,'department','Which information should be recorded when reporting a quality issue? Select all correct answers.','multiple_select',NULL,NULL,1,'{\"title\":\"Q7. Information to Record When Reporting Quality Issue\",\"section\":\"2\",\"section_title\":\"Section 2 — Multiple Select\",\"options\":[{\"key\":\"A\",\"text\":\"A description of the issue\"},{\"key\":\"B\",\"text\":\"Evidence or examples of the issue\"},{\"key\":\"C\",\"text\":\"The potential impact and corrective action taken\"},{\"key\":\"D\",\"text\":\"Unverified assumptions presented as facts\"}],\"correct_answer\":null,\"correct_answers\":[\"A\",\"B\",\"C\"],\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answers: A, B, C. A description of the issue; Evidence or examples of the issue; The potential impact and corrective action taken\"}',180,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(308,1,NULL,NULL,5,'department','Quality checks should be performed only after a project is completely finished.','true_false',NULL,NULL,1,'{\"title\":\"Q8. Timing of Quality Checks\",\"section\":\"3\",\"section_title\":\"Section 3 — True/False\",\"options\":[{\"key\":\"True\",\"text\":\"True\"},{\"key\":\"False\",\"text\":\"False\"}],\"correct_answer\":\"False\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: False (Quality checks should be integrated throughout the process, not just at the end)\"}',90,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(309,1,NULL,NULL,5,'department','Documenting recurring errors can help a team identify patterns and prevent the same problems from happening again.','true_false',NULL,NULL,1,'{\"title\":\"Q9. Documenting Recurring Errors\",\"section\":\"3\",\"section_title\":\"Section 3 — True/False\",\"options\":[{\"key\":\"True\",\"text\":\"True\"},{\"key\":\"False\",\"text\":\"False\"}],\"correct_answer\":\"True\",\"correct_answers\":null,\"model_answer\":null,\"criteria_list\":null,\"guidance\":\"Correct Answer: True (Documenting errors enables trend analysis and proactive prevention)\"}',90,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(310,1,NULL,NULL,5,'department','What is the difference between Quality Assurance (QA) and Quality Control (QC)?','short_answer',NULL,NULL,10,'{\"title\":\"Q10. Difference Between QA and QC\",\"section\":\"4\",\"section_title\":\"Section 4 — Short Answer\",\"options\":null,\"correct_answer\":null,\"correct_answers\":null,\"model_answer\":\"Quality Assurance focuses on improving processes to prevent defects, while Quality Control focuses on checking outputs to identify defects.\",\"criteria_list\":[\"QA focuses on process improvement and defect prevention\",\"QC focuses on product/output inspection and defect identification\",\"Clear conceptual understanding of proactive vs reactive quality mechanisms\"],\"guidance\":\"Model answer: Quality Assurance focuses on improving processes to prevent defects, while Quality Control focuses on checking outputs to identify defects.\"}',240,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(311,1,NULL,NULL,5,'department','How would you ensure that a report or business document is accurate before submitting it?','short_answer',NULL,NULL,10,'{\"title\":\"Q11. Ensuring Document Accuracy Before Submission\",\"section\":\"4\",\"section_title\":\"Section 4 — Short Answer\",\"options\":null,\"correct_answer\":null,\"correct_answers\":null,\"model_answer\":\"Review the information, verify data against reliable sources, check for missing or inconsistent details, and follow the established quality checklist.\",\"criteria_list\":[\"Reviews the information carefully\",\"Verifies data against primary/reliable sources\",\"Checks for missing or inconsistent details\",\"Follows established quality checklists or standard review procedures\"],\"guidance\":\"Model answer: Review the information, verify data against reliable sources, check for missing or inconsistent details, and follow the established quality checklist.\"}',180,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(312,1,NULL,NULL,5,'department','Why is it important to document quality issues and corrective actions?','short_answer',NULL,NULL,10,'{\"title\":\"Q12. Importance of Documenting Issues and Corrective Actions\",\"section\":\"4\",\"section_title\":\"Section 4 — Short Answer\",\"options\":null,\"correct_answer\":null,\"correct_answers\":null,\"model_answer\":\"Documentation helps track recurring problems, identify root causes, maintain accountability, and prevent similar issues in the future.\",\"criteria_list\":[\"Tracks recurring problems and trends\",\"Helps identify underlying root causes\",\"Maintains team accountability and audit trails\",\"Prevents similar issues from occurring in the future\"],\"guidance\":\"Model answer: Documentation helps track recurring problems, identify root causes, maintain accountability, and prevent similar issues in the future.\"}',180,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(313,1,NULL,NULL,5,'department','Repeated Data Errors\n\nYou discover that the same type of data-entry error has occurred several times in a company report. What steps would you take to investigate and prevent the error from recurring?','scenario',NULL,NULL,10,'{\"title\":\"Q13. Repeated Data Errors\",\"section\":\"5\",\"section_title\":\"Section 5 — Scenario-Based\",\"options\":null,\"correct_answer\":null,\"correct_answers\":null,\"model_answer\":\"Verify the errors, investigate their root cause, correct the affected records, identify preventive actions such as validation rules or staff training, and monitor future reports to confirm the issue is resolved.\",\"criteria_list\":[\"Step 1: Verify data errors and determine impact/scope\",\"Step 2: Investigate root cause (systemic validation, training gap, user interface issue)\",\"Step 3: Correct affected historical records\",\"Step 4: Implement preventive measures (validation rules, SOP update, staff training)\",\"Step 5: Monitor future reports to verify issue resolution\"],\"guidance\":\"Model answer: Verify the errors, investigate their root cause, correct the affected records, identify preventive actions such as validation rules or staff training, and monitor future reports to confirm the issue is resolved.\"}',300,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(314,1,NULL,NULL,5,'department','Quality Standard Not Met\n\nYou review a completed deliverable and discover that it does not meet the company\'s defined quality standards. The deadline is approaching. What would you do?','scenario',NULL,NULL,10,'{\"title\":\"Q14. Quality Standard Not Met\",\"section\":\"5\",\"section_title\":\"Section 5 — Scenario-Based\",\"options\":null,\"correct_answer\":null,\"correct_answers\":null,\"model_answer\":\"Identify the quality gaps, assess their impact, inform the relevant manager, prioritize essential corrections, and communicate a realistic completion timeline. Do not approve or release work that fails critical quality requirements without proper authorization.\",\"criteria_list\":[\"Identifies specific quality gaps and assesses business/client impact\",\"Escalates to relevant manager with transparent assessment\",\"Prioritizes essential corrections needed for compliance\",\"Communicates realistic completion timeline to stakeholders\",\"Refuses to approve or release substandard work without proper authorization\"],\"guidance\":\"Model answer: Identify the quality gaps, assess their impact, inform the relevant manager, prioritize essential corrections, and communicate a realistic completion timeline. Do not approve or release work that fails critical quality requirements without proper authorization.\"}',300,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(315,1,NULL,NULL,5,'department','Conflicting Quality Results\n\nTwo team members review the same dataset and report different results. How would you investigate the disagreement and determine which result is correct?','scenario',NULL,NULL,10,'{\"title\":\"Q15. Conflicting Quality Results\",\"section\":\"5\",\"section_title\":\"Section 5 — Scenario-Based\",\"options\":null,\"correct_answer\":null,\"correct_answers\":null,\"model_answer\":\"Verify the source data, compare the calculation methods and applicable criteria, repeat the analysis where necessary, document the findings, and communicate the verified result to both team members.\",\"criteria_list\":[\"Verifies raw source data integrity and version alignment\",\"Compares calculation methods, formulas, and criteria used by each reviewer\",\"Performs independent verification or recalculation where necessary\",\"Documents the investigation methodology and evidence\",\"Communicates the verified result constructively to both team members\"],\"guidance\":\"Model answer: Verify the source data, compare the calculation methods and applicable criteria, repeat the analysis where necessary, document the findings, and communicate the verified result to both team members.\"}',300,1.00,0,'2026-10-15 00:08:59','2026-10-22 19:39:11'),(316,2,3,14,NULL,'hr','what is your strength ?','short_answer',NULL,NULL,10,NULL,120,1.00,1,'2026-10-22 18:06:19','2026-10-22 18:06:19'),(317,7,14,10,NULL,'department','Question: What is the primary source of demand for products in a B2B (Business-to-Business) market?','mcq','{\"A\":\"Government regulations\",\"B\":\"Derived demand from final consumers\",\"C\":\"Direct impulse buying by individuals\",\"D\":\"Social media viral trends\"}','B',10,NULL,120,1.00,0,'2026-10-22 18:23:48','2026-10-22 20:29:21'),(318,7,14,10,NULL,'department','Which of the following is a type of B2B model?','mcq','{\"A\":\"Peer-to-peer\",\"B\":\"Sell-side marketplace\",\"C\":\"Crowdfunding\",\"D\":\"Influencer marketing\"}','B',10,NULL,120,1.00,0,'2026-10-22 18:55:04','2026-10-22 20:29:21'),(319,7,14,10,NULL,'department','Strategic sourcing involves:','mcq','{\"A\":\"One-time purchases\",\"B\":\"Long-term contracts and negotiation\",\"C\":\"Freelance hiring\",\"D\":\"External PR agencies\"}','B',10,NULL,120,1.00,0,'2026-10-22 19:09:03','2026-10-22 20:29:21'),(320,7,14,10,NULL,'department','In a B2B buying center, which role is responsible for the actual negotiation of terms, prices, and vendor selection?','multiple_select','{\"A\":\"Initiator\",\"B\":\"Gatekeeper\",\"C\":\"Buyer\",\"D\":\"• User\"}','A, C',10,NULL,120,1.00,0,'2026-10-22 19:11:00','2026-10-22 20:29:21'),(321,7,14,10,NULL,'department','A \"Buying Center\" is a formal, permanent department explicitly listed on an organization\'s structural chart to handle all purchasing decisions.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',10,NULL,120,1.00,0,'2026-10-22 19:11:29','2026-10-22 20:29:21'),(322,1,NULL,NULL,NULL,'department','What is the primary purpose of software testing?','mcq','{\"A\":\"To increase the number of features\",\"B\":\"To identify defects and verify requirements\",\"C\":\"To design the user interface\",\"D\":\"To reduce documentation\"}','B',1,'To identify defects and verify requirements against system specifications.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(323,1,NULL,NULL,NULL,'department','What is a test case?','mcq','{\"A\":\"A list of employee details\",\"B\":\"A set of steps, inputs, and expected results used to test functionality\",\"C\":\"A programming language\",\"D\":\"A database backup\"}','B',1,'A documented set of steps, inputs, preconditions, and expected outcomes to verify functionality.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(324,1,NULL,NULL,NULL,'department','Which testing checks individual components of an application?','mcq','{\"A\":\"System testing\",\"B\":\"Acceptance testing\",\"C\":\"Unit testing\",\"D\":\"Performance testing\"}','C',1,'Unit testing checks individual components, functions, or modules of an application in isolation.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(325,1,NULL,NULL,NULL,'department','What is regression testing?','mcq','{\"A\":\"Testing only new employees\",\"B\":\"Checking whether changes have broken existing functionality\",\"C\":\"Deleting old test cases\",\"D\":\"Testing without requirements\"}','B',1,'Re-testing existing functionalities to ensure new code changes or bug fixes have not introduced side effects.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(326,1,NULL,NULL,NULL,'department','Which defect should generally receive the highest priority?','mcq','{\"A\":\"A minor spelling mistake\",\"B\":\"A slightly misaligned icon\",\"C\":\"A payment failure affecting all users\",\"D\":\"A small color difference\"}','C',1,'A payment failure affecting all users is a critical revenue blocker requiring immediate triage and fix.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(327,1,NULL,NULL,NULL,'department','Which details should a good bug report contain?','multiple_select','{\"A\":\"Steps to reproduce\",\"B\":\"Expected result\",\"C\":\"Actual result\",\"D\":\"Personal opinions about the developer\",\"E\":\"Relevant screenshots or logs\"}','A, B, C, E',2,'A quality bug report must include steps to reproduce, expected result, actual result, and attachments (screenshots/logs). Personal opinions must never be included.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(328,1,NULL,NULL,NULL,'department','Which types of testing can help evaluate a web application?','multiple_select','{\"A\":\"Functional testing\",\"B\":\"Performance testing\",\"C\":\"Security testing\",\"D\":\"Usability testing\",\"E\":\"Employee attendance testing\"}','A, B, C, D',2,'Web applications should be assessed across functional, performance, security, and usability dimensions.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(329,1,NULL,NULL,NULL,'department','Testing can help identify defects, but it cannot guarantee that software is completely defect-free.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'Testing shows the presence of defects, not their complete absence (ISTQB principle).',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(330,1,NULL,NULL,NULL,'department','A tester should close a defect without verifying the fix.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'Testers must always reproduce the scenario on the updated build and verify the fix before closing any defect.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(331,1,NULL,NULL,NULL,'department','What is the difference between quality assurance and quality control?','short_answer',NULL,'Quality assurance focuses on improving processes to prevent defects. Quality control focuses on checking the product to identify defects.',3,'Quality assurance focuses on improving processes to prevent defects. Quality control focuses on checking the product to identify defects.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(332,1,NULL,NULL,NULL,'department','What is the difference between severity and priority?','short_answer',NULL,'Severity describes the impact of a defect; priority describes how urgently it should be fixed.',3,'Severity describes the impact of a defect; priority describes how urgently it should be fixed.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(333,1,NULL,NULL,NULL,'department','What is boundary value analysis?','short_answer',NULL,'A testing technique that checks values at and around the minimum and maximum limits of an input range.',3,'A testing technique that checks values at and around the minimum and maximum limits of an input range.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(334,1,NULL,NULL,NULL,'department','A login page works correctly with valid credentials but crashes when a user enters a very long password. What would you do?','scenario',NULL,'Reproduce the issue, record test data and steps, capture evidence, report severity, and retest after the fix.',5,'Reproduce the issue, record test data and steps, capture evidence, report severity, and retest after the fix.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(335,1,NULL,NULL,NULL,'department','A developer says that a defect cannot be reproduced, but you can reproduce it consistently. How would you handle this?','scenario',NULL,'Share exact steps, environment, browser/device details, test data, and logs or recordings; collaborate to reproduce the issue.',5,'Share exact steps, environment, browser/device details, test data, and logs or recordings; collaborate to reproduce the issue.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(336,1,NULL,NULL,NULL,'department','A critical defect is discovered shortly before a release. The project manager wants to release the software on time. What would you recommend?','scenario',NULL,'Explain risk and user impact, document evidence, communicate with stakeholders, and recommend a release decision based on risk and release criteria.',5,'Explain risk and user impact, document evidence, communicate with stakeholders, and recommend a release decision based on risk and release criteria.',180,1.00,1,'2026-10-22 19:39:11','2026-10-22 19:39:11'),(337,2,NULL,NULL,NULL,'department','Which JavaScript keyword declares a block-scoped variable that can be reassigned?','mcq','{\"A\":\"const\",\"B\":\"let\",\"C\":\"static\",\"D\":\"final\"}','B',1,'let declares a block-scoped mutable variable that can be reassigned.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(338,2,NULL,NULL,NULL,'department','Which React feature allows a component to manage its own changing data?','mcq','{\"A\":\"State\",\"B\":\"HTML attributes only\",\"C\":\"SQL joins\",\"D\":\"CSS selectors\"}','A',1,'State allows React components to maintain, track, and update internal dynamic data between renders.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(339,2,NULL,NULL,NULL,'department','What is the main purpose of an API?','mcq','{\"A\":\"To style a webpage\",\"B\":\"To enable communication between software systems\",\"C\":\"To store images exclusively\",\"D\":\"To compile CSS\"}','B',1,'APIs define contracts and protocols allowing distinct software applications to communicate and exchange data.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(340,2,NULL,NULL,NULL,'department','Which Java concept allows a subclass to provide its own implementation of a parent class method?','mcq','{\"A\":\"Encapsulation\",\"B\":\"Method overriding\",\"C\":\"Constructor overloading\",\"D\":\"Type casting\"}','B',1,'Method overriding allows a subclass to provide a specific implementation of a method already declared in its superclass.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(341,2,NULL,NULL,NULL,'department','What is the purpose of Git?','mcq','{\"A\":\"Version control\",\"B\":\"Image editing\",\"C\":\"Database hosting only\",\"D\":\"Browser automation only\"}','A',1,'Git is a distributed version control system for tracking changes in source code during software development.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(342,2,NULL,NULL,NULL,'department','Which are valid practices for writing maintainable code?','multiple_select','{\"A\":\"Use meaningful variable names\",\"B\":\"Break complex logic into reusable functions\",\"C\":\"Duplicate the same logic everywhere\",\"D\":\"Handle errors appropriately\",\"E\":\"Add useful comments when needed\"}','A, B, D, E',2,'Meaningful naming, modularization, proper error handling, and helpful documentation foster clean, maintainable architecture.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(343,2,NULL,NULL,NULL,'department','Which HTTP methods are commonly used when working with REST APIs?','multiple_select','{\"A\":\"GET\",\"B\":\"POST\",\"C\":\"PUT\",\"D\":\"DELETE\",\"E\":\"PAINT\"}','A, B, C, D',2,'Standard REST verbs are GET (read), POST (create), PUT/PATCH (update), and DELETE (remove).',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(344,2,NULL,NULL,NULL,'department','React components can be reused in different parts of an application.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. Component reusability is a foundational architectural principle of React.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(345,2,NULL,NULL,NULL,'department','Client-side validation alone is sufficient to secure all data submitted to a server.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. Client-side checks can be bypassed; robust server-side validation and sanitization are strictly required.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(346,2,NULL,NULL,NULL,'department','What is the difference between let and const in JavaScript?','short_answer',NULL,'Both are block-scoped. A let variable can be reassigned, while a const binding cannot be reassigned.',3,'Both are block-scoped. A let variable can be reassigned, while a const binding cannot be reassigned.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(347,2,NULL,NULL,NULL,'department','What is the difference between frontend and backend development?','short_answer',NULL,'Frontend handles the user interface and client-side interactions; backend handles server-side logic, data processing, and services.',3,'Frontend handles the user interface and client-side interactions; backend handles server-side logic, data processing, and services.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(348,2,NULL,NULL,NULL,'department','What is the purpose of exception handling in Java?','short_answer',NULL,'It allows programs to handle runtime errors gracefully using mechanisms such as try, catch, and finally.',3,'It allows programs to handle runtime errors gracefully using mechanisms such as try, catch, and finally.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(349,2,NULL,NULL,NULL,'department','A React page displays outdated information after a user updates a record. How would you investigate and fix it?','scenario',NULL,'Check state updates, API responses, component rendering, and asynchronous logic; update the correct state after a successful response.',5,'Check state updates, API responses, component rendering, and asynchronous logic; update the correct state after a successful response.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(350,2,NULL,NULL,NULL,'department','Your API returns a 500 Internal Server Error. What steps would you take to identify the cause?','scenario',NULL,'Inspect server logs, reproduce the request, check input data, trace backend logic, and verify database or dependency failures.',5,'Inspect server logs, reproduce the request, check input data, trace backend logic, and verify database or dependency failures.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(351,2,NULL,NULL,NULL,'department','Two developers modify the same file and a Git merge conflict occurs. How would you resolve it?','scenario',NULL,'Review both changes, discuss conflicting logic, resolve the conflict carefully, run tests, and commit the resolved file.',5,'Review both changes, discuss conflicting logic, resolve the conflict carefully, run tests, and commit the resolved file.',180,1.00,1,'2026-10-22 19:57:25','2026-10-22 19:57:25'),(352,3,NULL,NULL,NULL,'department','What is the main purpose of project planning?','mcq','{\"A\":\"To eliminate all communication\",\"B\":\"To define objectives, timelines, resources, and responsibilities\",\"C\":\"To increase unnecessary meetings\",\"D\":\"To avoid tracking progress\"}','B',1,'To define objectives, timelines, resources, and responsibilities.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(353,3,NULL,NULL,NULL,'department','What should a manager do first when two urgent tasks compete for the same resources?','mcq','{\"A\":\"Ignore both tasks\",\"B\":\"Evaluate business impact, deadlines, and dependencies\",\"C\":\"Assign both tasks to the same person without discussion\",\"D\":\"Cancel the project immediately\"}','B',1,'Evaluate business impact, deadlines, and dependencies.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(354,3,NULL,NULL,NULL,'department','Which is an example of a measurable performance indicator?','mcq','{\"A\":\"The team seems busy\",\"B\":\"Everyone looks motivated\",\"C\":\"Percentage of project milestones completed on time\",\"D\":\"The office feels productive\"}','C',1,'Percentage of project milestones completed on time.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(355,3,NULL,NULL,NULL,'department','What is delegation?','mcq','{\"A\":\"Assigning appropriate responsibilities and authority to team members\",\"B\":\"Avoiding responsibility\",\"C\":\"Completing every task alone\",\"D\":\"Removing all deadlines\"}','A',1,'Assigning appropriate responsibilities and authority to team members.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(356,3,NULL,NULL,NULL,'department','Which approach is best when a team repeatedly misses deadlines?','mcq','{\"A\":\"Blame one employee immediately\",\"B\":\"Examine workload, blockers, estimates, and dependencies\",\"C\":\"Stop tracking tasks\",\"D\":\"Increase deadlines without analysis\"}','B',1,'Examine workload, blockers, estimates, and dependencies.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(357,3,NULL,NULL,NULL,'department','Which activities are part of effective project management?','multiple_select','{\"A\":\"Defining project scope\",\"B\":\"Tracking milestones\",\"C\":\"Managing risks\",\"D\":\"Communicating progress\",\"E\":\"Ignoring resource constraints\"}','A, B, C, D',2,'Defining project scope, tracking milestones, managing risks, and communicating progress.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(358,3,NULL,NULL,NULL,'department','Which actions can improve team performance?','multiple_select','{\"A\":\"Giving constructive feedback\",\"B\":\"Setting clear expectations\",\"C\":\"Recognizing good performance\",\"D\":\"Resolving blockers\",\"E\":\"Withholding important information\"}','A, B, C, D',2,'Giving constructive feedback, setting clear expectations, recognizing good performance, and resolving blockers.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(359,3,NULL,NULL,NULL,'department','Effective delegation includes making responsibilities and expected outcomes clear.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. Clear responsibilities and outcomes are vital for successful delegation.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(360,3,NULL,NULL,NULL,'department','A project manager should never revise a plan after receiving new information.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. Project plans must adapt and update when new requirements, constraints, or information emerge.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(361,3,NULL,NULL,NULL,'department','What is the difference between a goal and a KPI?','short_answer',NULL,'A goal describes the desired outcome; a KPI measures progress or performance toward that outcome.',3,'A goal describes the desired outcome; a KPI measures progress or performance toward that outcome.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(362,3,NULL,NULL,NULL,'department','How would you prioritize tasks when multiple deadlines overlap?','short_answer',NULL,'Assess urgency, business impact, dependencies, effort, and available resources; communicate priorities clearly.',3,'Assess urgency, business impact, dependencies, effort, and available resources; communicate priorities clearly.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(363,3,NULL,NULL,NULL,'department','What is risk management in a project?','short_answer',NULL,'Identifying potential problems, evaluating their likelihood and impact, and planning mitigation or contingency actions.',3,'Identifying potential problems, evaluating their likelihood and impact, and planning mitigation or contingency actions.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(364,3,NULL,NULL,NULL,'department','Your team is two weeks behind schedule, and the client expects delivery on the original date. What would you do?','scenario',NULL,'Identify root causes, review scope and dependencies, prioritize essential deliverables, allocate resources, and communicate a realistic recovery plan.',5,'Identify root causes, review scope and dependencies, prioritize essential deliverables, allocate resources, and communicate a realistic recovery plan.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(365,3,NULL,NULL,NULL,'department','Two team members disagree about how a project should be completed. How would you resolve the conflict?','scenario',NULL,'Hear both perspectives, compare evidence and objectives, agree on decision criteria, and document responsibilities and next steps.',5,'Hear both perspectives, compare evidence and objectives, agree on decision criteria, and document responsibilities and next steps.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(366,3,NULL,NULL,NULL,'department','A project is within budget but is not meeting its expected quality standards. How would you respond?','scenario',NULL,'Assess quality gaps, identify root causes, establish corrective actions, protect essential quality requirements, and revise the delivery plan if necessary.',5,'Assess quality gaps, identify root causes, establish corrective actions, protect essential quality requirements, and revise the delivery plan if necessary.',180,1.00,1,'2026-10-22 20:03:03','2026-10-22 20:03:03'),(367,4,NULL,NULL,NULL,'department','What is the primary purpose of lead qualification?','mcq','{\"A\":\"To contact every lead repeatedly\",\"B\":\"To determine whether a lead fits the target customer profile and has potential to buy\",\"C\":\"To close every lead immediately\",\"D\":\"To avoid asking discovery questions\"}','B',1,'To determine whether a lead fits the target customer profile and has potential to buy.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(368,4,NULL,NULL,NULL,'department','What does B2B stand for?','mcq','{\"A\":\"Business-to-Business\",\"B\":\"Buyer-to-Brand\",\"C\":\"Business-to-Browser\",\"D\":\"Brand-to-Backend\"}','A',1,'Business-to-Business.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(369,4,NULL,NULL,NULL,'department','What is the best first step when contacting a potential client?','mcq','{\"A\":\"Immediately demand a purchase\",\"B\":\"Understand the prospect\'s needs and business context\",\"C\":\"Send the same long message repeatedly\",\"D\":\"Promise results without evidence\"}','B',1,'Understand the prospect\'s needs and business context.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(370,4,NULL,NULL,NULL,'department','Which information is most useful when qualifying a sales lead?','mcq','{\"A\":\"Prospect\'s favorite movie\",\"B\":\"Business need, budget, decision authority, and timing\",\"C\":\"Personal gossip\",\"D\":\"Number of social media photos\"}','B',1,'Business need, budget, decision authority, and timing.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(371,4,NULL,NULL,NULL,'department','What is the purpose of a CRM system in sales?','mcq','{\"A\":\"To track leads, interactions, and sales opportunities\",\"B\":\"To replace every customer conversation\",\"C\":\"To create graphic designs\",\"D\":\"To delete customer records automatically\"}','A',1,'To track leads, interactions, and sales opportunities.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(372,4,NULL,NULL,NULL,'department','Which are good practices when conducting B2B prospecting?','multiple_select','{\"A\":\"Research the target company\",\"B\":\"Personalize relevant outreach\",\"C\":\"Identify appropriate decision-makers\",\"D\":\"Track follow-ups in the CRM\",\"E\":\"Make unsupported claims about results\"}','A, B, C, D',2,'Research the target company, personalize relevant outreach, identify appropriate decision-makers, and track follow-ups in the CRM.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(373,4,NULL,NULL,NULL,'department','Which activities help maintain a healthy sales pipeline?','multiple_select','{\"A\":\"Regularly updating opportunity stages\",\"B\":\"Following up at appropriate intervals\",\"C\":\"Recording customer objections\",\"D\":\"Forecasting using current deal information\",\"E\":\"Marking every lead as won\"}','A, B, C, D',2,'Regularly updating opportunity stages, following up at appropriate intervals, recording customer objections, and forecasting using current deal information.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(374,4,NULL,NULL,NULL,'department','A sales representative should understand a prospect\'s needs before recommending a solution.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. Understanding prospect needs before prescribing solutions is fundamental to consultative sales.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(375,4,NULL,NULL,NULL,'department','A lead should always be marked as qualified simply because the person replied to an email.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. A reply indicates engagement, but qualification requires assessing fit, need, budget, and decision authority.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(376,4,NULL,NULL,NULL,'department','What is the difference between a lead and a sales-qualified lead?','short_answer',NULL,'A lead is a potential customer; a sales-qualified lead has been assessed against relevant criteria and is considered ready for sales engagement.',3,'A lead is a potential customer; a sales-qualified lead has been assessed against relevant criteria and is considered ready for sales engagement.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(377,4,NULL,NULL,NULL,'department','What is an ideal customer profile (ICP)?','short_answer',NULL,'A description of the types of companies most likely to benefit from and purchase a business\'s product or service.',3,'A description of the types of companies most likely to benefit from and purchase a business\'s product or service.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(378,4,NULL,NULL,NULL,'department','How would you handle a prospect who says your service is too expensive?','short_answer',NULL,'Understand the objection, explore the prospect\'s priorities, explain relevant value and evidence, and discuss suitable options without making false promises.',3,'Understand the objection, explore the prospect\'s priorities, explain relevant value and evidence, and discuss suitable options without making false promises.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(379,4,NULL,NULL,NULL,'department','A prospect agrees to a discovery call but does not attend. What would you do?','scenario',NULL,'Send a polite follow-up, offer alternative times, check whether the timing remains suitable, and update the CRM.',5,'Send a polite follow-up, offer alternative times, check whether the timing remains suitable, and update the CRM.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(380,4,NULL,NULL,NULL,'department','A prospect wants a guaranteed number of leads, but your company cannot guarantee that outcome. How would you respond?','scenario',NULL,'Set honest expectations, explain the service scope and measurable deliverables, share substantiated evidence, and avoid unsupported guarantees.',5,'Set honest expectations, explain the service scope and measurable deliverables, share substantiated evidence, and avoid unsupported guarantees.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(381,4,NULL,NULL,NULL,'department','You have 50 new leads but limited time to contact them. How would you prioritize them?','scenario',NULL,'Apply ICP fit, intent signals, business need, potential value, and engagement or qualification data; prioritize transparently and record activity.',5,'Apply ICP fit, intent signals, business need, potential value, and engagement or qualification data; prioritize transparently and record activity.',180,1.00,1,'2026-10-22 20:08:12','2026-10-22 20:08:12'),(382,5,NULL,NULL,NULL,'department','What is the primary purpose of an HR screening interview?','mcq','{\"A\":\"To guarantee selection\",\"B\":\"To assess the candidate\'s suitability against role requirements\",\"C\":\"To discuss unrelated personal matters\",\"D\":\"To avoid checking qualifications\"}','B',1,'To assess the candidate\'s suitability against role requirements.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(383,5,NULL,NULL,NULL,'department','What does onboarding mean?','mcq','{\"A\":\"Advertising a vacancy\",\"B\":\"Integrating a new employee into the organization\",\"C\":\"Rejecting an application\",\"D\":\"Closing a project\"}','B',1,'Integrating a new employee into the organization.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(384,5,NULL,NULL,NULL,'department','Which document typically outlines an employee\'s job responsibilities?','mcq','{\"A\":\"Job description\",\"B\":\"Marketing brochure\",\"C\":\"Purchase invoice\",\"D\":\"Database backup\"}','A',1,'Job description.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(385,5,NULL,NULL,NULL,'department','Why should candidate information be handled confidentially?','mcq','{\"A\":\"To prevent authorized hiring managers from working\",\"B\":\"To protect personal information and restrict unauthorized access\",\"C\":\"To avoid maintaining records\",\"D\":\"To publish candidate details publicly\"}','B',1,'To protect personal information and restrict unauthorized access.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(386,5,NULL,NULL,NULL,'department','Which is the most appropriate basis for selecting a candidate?','mcq','{\"A\":\"Personal favoritism\",\"B\":\"Relevant skills, qualifications, and job-related assessment\",\"C\":\"Unrelated personal characteristics\",\"D\":\"The order in which applications arrived, regardless of requirements\"}','B',1,'Relevant skills, qualifications, and job-related assessment.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(387,5,NULL,NULL,NULL,'department','Which information may be relevant to a candidate\'s recruitment record?','multiple_select','{\"A\":\"Contact details\",\"B\":\"Relevant qualifications\",\"C\":\"Interview evaluation\",\"D\":\"Application status\",\"E\":\"Unrelated personal gossip\"}','A, B, C, D',2,'Contact details, Relevant qualifications, Interview evaluation, and Application status are legitimate recruitment record items.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(388,5,NULL,NULL,NULL,'department','Which activities are part of employee onboarding?','multiple_select','{\"A\":\"Collecting required employment documents\",\"B\":\"Explaining company policies\",\"C\":\"Arranging access and equipment\",\"D\":\"Introducing the employee to the team\",\"E\":\"Sharing confidential employee records with everyone\"}','A, B, C, D',2,'Collecting required employment documents, Explaining company policies, Arranging access and equipment, and Introducing the employee to the team.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(389,5,NULL,NULL,NULL,'department','Interview evaluations should be based on job-related evidence and consistent assessment criteria.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. Evaluations must be objective, job-related, and standardized.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(390,5,NULL,NULL,NULL,'department','Every candidate should receive an offer letter before the selection decision is finalized.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. Offer letters are only extended after final selection approval.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(391,5,NULL,NULL,NULL,'department','What is the difference between recruitment and selection?','short_answer',NULL,'Recruitment attracts potential candidates; selection evaluates applicants and identifies the most suitable candidate.',3,'Recruitment attracts potential candidates; selection evaluates applicants and identifies the most suitable candidate.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(392,5,NULL,NULL,NULL,'department','What is an employee onboarding checklist?','short_answer',NULL,'A structured list of tasks such as document collection, policy orientation, system access, equipment allocation, and introductions.',3,'A structured list of tasks such as document collection, policy orientation, system access, equipment allocation, and introductions.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(393,5,NULL,NULL,NULL,'department','How would you maintain confidentiality in an HRMS?','short_answer',NULL,'Use role-based access, secure authentication, restricted document permissions, appropriate retention policies, and audit logs.',3,'Use role-based access, secure authentication, restricted document permissions, appropriate retention policies, and audit logs.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(394,5,NULL,NULL,NULL,'department','A candidate passes the HR round but performs poorly in the technical round. How would you update the candidate\'s status?','scenario',NULL,'Record the technical evaluator\'s feedback, update the relevant round result, apply established selection criteria, and communicate the next step according to company policy.',5,'Record the technical evaluator\'s feedback, update the relevant round result, apply established selection criteria, and communicate the next step according to company policy.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(395,5,NULL,NULL,NULL,'department','A candidate\'s CV contains information that conflicts with their application form. What would you do?','scenario',NULL,'Verify the discrepancy respectfully, ask the candidate for clarification, document the outcome, and make a decision based on verified information.',5,'Verify the discrepancy respectfully, ask the candidate for clarification, document the outcome, and make a decision based on verified information.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(396,5,NULL,NULL,NULL,'department','A selected candidate has not submitted all required joining documents before the joining date. How would you handle this?','scenario',NULL,'Identify missing documents, send a secure reminder, confirm acceptable submission timelines with the appropriate HR authority, and track completion without exposing sensitive information.',5,'Identify missing documents, send a secure reminder, confirm acceptable submission timelines with the appropriate HR authority, and track completion without exposing sensitive information.',180,1.00,1,'2026-10-22 20:18:18','2026-10-22 20:18:18'),(397,6,NULL,NULL,NULL,'department','What is the primary objective of business operations?','mcq','{\"A\":\"To make daily work inefficient\",\"B\":\"To ensure processes run effectively and consistently\",\"C\":\"To eliminate all reporting\",\"D\":\"To avoid measuring performance\"}','B',1,'To ensure processes run effectively and consistently.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(398,6,NULL,NULL,NULL,'department','What is a standard operating procedure (SOP)?','mcq','{\"A\":\"A documented set of instructions for carrying out a process\",\"B\":\"An employee\'s personal opinion\",\"C\":\"A marketing campaign\",\"D\":\"A database query\"}','A',1,'A documented set of instructions for carrying out a process.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(399,6,NULL,NULL,NULL,'department','What does a process bottleneck mean?','mcq','{\"A\":\"A step that limits the overall flow or capacity of a process\",\"B\":\"A completed project\",\"C\":\"An employee promotion\",\"D\":\"A new office location\"}','A',1,'A step that limits the overall flow or capacity of a process.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(400,6,NULL,NULL,NULL,'department','Which metric best measures on-time task completion?','mcq','{\"A\":\"Number of office chairs\",\"B\":\"Percentage of tasks completed by their deadlines\",\"C\":\"Number of emails received\",\"D\":\"Number of files stored\"}','B',1,'Percentage of tasks completed by their deadlines.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(401,6,NULL,NULL,NULL,'department','What should be done when an operational process repeatedly fails?','mcq','{\"A\":\"Ignore the failures\",\"B\":\"Investigate the root cause and implement corrective actions\",\"C\":\"Delete all process records\",\"D\":\"Continue without informing the responsible team\"}','B',1,'Investigate the root cause and implement corrective actions.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(402,6,NULL,NULL,NULL,'department','Which activities support efficient operations?','multiple_select','{\"A\":\"Documenting workflows\",\"B\":\"Tracking task completion\",\"C\":\"Identifying recurring delays\",\"D\":\"Coordinating across departments\",\"E\":\"Ignoring process deviations\"}','A, B, C, D',2,'Documenting workflows, Tracking task completion, Identifying recurring delays, and Coordinating across departments.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(403,6,NULL,NULL,NULL,'department','Which information should an operational task record generally contain?','multiple_select','{\"A\":\"Task description\",\"B\":\"Assigned owner\",\"C\":\"Due date\",\"D\":\"Current status\",\"E\":\"Unrelated private information\"}','A, B, C, D',2,'Task description, Assigned owner, Due date, and Current status.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(404,6,NULL,NULL,NULL,'department','Standardized processes can help improve consistency and reduce avoidable errors.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. Standardized processes establish operational reliability and minimize deviation.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(405,6,NULL,NULL,NULL,'department','Operational reports are useful only when a problem has already occurred.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. Reports allow proactive monitoring and performance optimization before issues escalate.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(406,6,NULL,NULL,NULL,'department','What is a standard operating procedure, and why is it useful?','short_answer',NULL,'An SOP documents how to perform a task consistently, helping with training, quality, accountability, and error reduction.',3,'An SOP documents how to perform a task consistently, helping with training, quality, accountability, and error reduction.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(407,6,NULL,NULL,NULL,'department','What is the difference between efficiency and effectiveness?','short_answer',NULL,'Efficiency concerns the resources used to achieve an outcome; effectiveness concerns whether the intended outcome is achieved.',3,'Efficiency concerns the resources used to achieve an outcome; effectiveness concerns whether the intended outcome is achieved.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(408,6,NULL,NULL,NULL,'department','What is root cause analysis?','short_answer',NULL,'A method of identifying the underlying reason for a problem rather than treating only its symptoms.',3,'A method of identifying the underlying reason for a problem rather than treating only its symptoms.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(409,6,NULL,NULL,NULL,'department','A daily report is delayed because three departments submit their information late. What would you do?','scenario',NULL,'Identify where delays occur, establish submission deadlines and ownership, automate reminders where possible, and track compliance.',5,'Identify where delays occur, establish submission deadlines and ownership, automate reminders where possible, and track compliance.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(410,6,NULL,NULL,NULL,'department','You discover that two employees are performing the same task while another critical task remains unassigned. How would you respond?','scenario',NULL,'Review task ownership, clarify responsibilities, rebalance workloads, assign the neglected task appropriately, and update the tracker.',5,'Review task ownership, clarify responsibilities, rebalance workloads, assign the neglected task appropriately, and update the tracker.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(411,6,NULL,NULL,NULL,'department','An important operational process fails just before a client deadline. How would you manage the situation?','scenario',NULL,'Assess the impact, notify relevant stakeholders, activate a suitable contingency plan, assign recovery actions, and document the root cause afterward.',5,'Assess the impact, notify relevant stakeholders, activate a suitable contingency plan, assign recovery actions, and document the root cause afterward.',180,1.00,1,'2026-10-22 20:23:38','2026-10-22 20:23:38'),(412,7,NULL,NULL,NULL,'department','What is the primary purpose of a primary key?','mcq','{\"A\":\"To uniquely identify each record in a table\",\"B\":\"To format database reports\",\"C\":\"To encrypt every column automatically\",\"D\":\"To duplicate rows\"}','A',1,'To uniquely identify each record in a table.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(413,7,NULL,NULL,NULL,'department','Which SQL statement retrieves data from a table?','mcq','{\"A\":\"SELECT\",\"B\":\"INSERT\",\"C\":\"DROP\",\"D\":\"UPDATE\"}','A',1,'SELECT.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(414,7,NULL,NULL,NULL,'department','Which SQL clause filters rows based on a condition?','mcq','{\"A\":\"ORDER BY\",\"B\":\"WHERE\",\"C\":\"GROUP BY\",\"D\":\"CREATE\"}','B',1,'WHERE.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(415,7,NULL,NULL,NULL,'department','What is the purpose of a foreign key?','mcq','{\"A\":\"To establish a relationship between tables and enforce referential integrity\",\"B\":\"To rename a database\",\"C\":\"To sort records alphabetically\",\"D\":\"To remove all constraints\"}','A',1,'To establish a relationship between tables and enforce referential integrity.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(416,7,NULL,NULL,NULL,'department','Which SQL command modifies existing records in a table?','mcq','{\"A\":\"SELECT\",\"B\":\"UPDATE\",\"C\":\"CREATE\",\"D\":\"GRANT\"}','B',1,'UPDATE.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(417,7,NULL,NULL,NULL,'department','Which are aggregate functions commonly available in SQL?','multiple_select','{\"A\":\"COUNT()\",\"B\":\"SUM()\",\"C\":\"AVG()\",\"D\":\"MAX()\",\"E\":\"PRINT()\"}','A, B, C, D',2,'COUNT(), SUM(), AVG(), and MAX() are standard SQL aggregate functions.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(418,7,NULL,NULL,NULL,'department','Which practices help maintain database reliability and security?','multiple_select','{\"A\":\"Regular backups\",\"B\":\"Appropriate access permissions\",\"C\":\"Database transactions where needed\",\"D\":\"Parameterized queries for user input\",\"E\":\"Sharing administrator credentials with everyone\"}','A, B, C, D',2,'Regular backups, Appropriate access permissions, Database transactions where needed, and Parameterized queries for user input.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(419,7,NULL,NULL,NULL,'department','A primary key must uniquely identify records and cannot contain NULL values.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. A primary key constraint enforces uniqueness and non-nullability on the column(s).',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(420,7,NULL,NULL,NULL,'department','The SQL condition WHERE salary > 50000 selects employees whose salary is exactly 50000 or higher.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. The strictly greater than operator (>) excludes 50000; (>=) would include it.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(421,7,NULL,NULL,NULL,'department','What is database normalization?','short_answer',NULL,'Organizing tables and relationships to reduce unnecessary duplication and prevent data anomalies.',3,'Organizing tables and relationships to reduce unnecessary duplication and prevent data anomalies.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(422,7,NULL,NULL,NULL,'department','What is the difference between DELETE and DROP in SQL?','short_answer',NULL,'DELETE removes rows from a table; DROP removes a database object such as a table itself. Exact behavior depends on the database system and transaction context.',3,'DELETE removes rows from a table; DROP removes a database object such as a table itself. Exact behavior depends on the database system and transaction context.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(423,7,NULL,NULL,NULL,'department','What is an SQL JOIN? Name two types.','short_answer',NULL,'A JOIN combines related rows from tables. Examples include INNER JOIN and LEFT JOIN.',3,'A JOIN combines related rows from tables. Examples include INNER JOIN and LEFT JOIN.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(424,7,NULL,NULL,NULL,'department','A query that previously ran quickly is now taking several seconds on a large employee table. How would you investigate?','scenario',NULL,'Examine the query and execution plan, check indexes and filtering conditions, assess table size and statistics, and optimize after measuring the impact.',5,'Examine the query and execution plan, check indexes and filtering conditions, assess table size and statistics, and optimize after measuring the impact.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(425,7,NULL,NULL,NULL,'department','An employee record is deleted, but related attendance records remain in the database. How would you prevent data inconsistencies?','scenario',NULL,'Review foreign key constraints and deletion rules, consider soft deletion or controlled cascading where appropriate, and preserve records according to retention requirements.',5,'Review foreign key constraints and deletion rules, consider soft deletion or controlled cascading where appropriate, and preserve records according to retention requirements.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(426,7,NULL,NULL,NULL,'department','An application sometimes inserts the same candidate twice when a user clicks Submit repeatedly. How would you solve this at the database level?','scenario',NULL,'Add a suitable unique constraint based on the business rule, use transactions where appropriate, handle duplicate-key errors, and implement application-level idempotency or duplicate prevention.',5,'Add a suitable unique constraint based on the business rule, use transactions where appropriate, handle duplicate-key errors, and implement application-level idempotency or duplicate prevention.',180,1.00,1,'2026-10-22 20:29:21','2026-10-22 20:29:21'),(427,8,NULL,NULL,NULL,'department','What is the main purpose of audience segmentation in email marketing?','mcq','{\"A\":\"To send identical emails to everyone\",\"B\":\"To group contacts based on relevant characteristics or behavior\",\"C\":\"To delete inactive customers automatically\",\"D\":\"To increase email size\"}','B',1,'To group contacts based on relevant characteristics or behavior.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(428,8,NULL,NULL,NULL,'department','Which metric measures the percentage of delivered emails that recipients clicked through?','mcq','{\"A\":\"Bounce rate\",\"B\":\"Click-through rate (CTR)\",\"C\":\"Unsubscribe count\",\"D\":\"Delivery time\"}','B',1,'Click-through rate (CTR).',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(429,8,NULL,NULL,NULL,'department','What is an email bounce?','mcq','{\"A\":\"An email that cannot be delivered to its intended recipient\",\"B\":\"An email opened multiple times\",\"C\":\"A successfully completed campaign\",\"D\":\"A recipient clicking a link\"}','A',1,'An email that cannot be delivered to its intended recipient.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(430,8,NULL,NULL,NULL,'department','What is the purpose of A/B testing in email marketing?','mcq','{\"A\":\"To compare variations and determine which performs better\",\"B\":\"To send duplicate emails without measurement\",\"C\":\"To remove campaign reports\",\"D\":\"To prevent personalization\"}','A',1,'To compare variations and determine which performs better.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(431,8,NULL,NULL,NULL,'department','Which practice can help improve email deliverability?','mcq','{\"A\":\"Purchasing random email lists\",\"B\":\"Sending to invalid addresses repeatedly\",\"C\":\"Maintaining permission-based lists and monitoring bounce rates\",\"D\":\"Hiding the unsubscribe option\"}','C',1,'Maintaining permission-based lists and monitoring bounce rates.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(432,8,NULL,NULL,NULL,'department','Which elements can be tested in an email campaign?','multiple_select','{\"A\":\"Subject line\",\"B\":\"Call-to-action text\",\"C\":\"Email content\",\"D\":\"Sending time\",\"E\":\"Employee payroll password\"}','A, B, C, D',2,'Subject line, Call-to-action text, Email content, and Sending time can all be tested.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(433,8,NULL,NULL,NULL,'department','Which metrics can help evaluate an email marketing campaign?','multiple_select','{\"A\":\"Delivery rate\",\"B\":\"Click-through rate\",\"C\":\"Conversion rate\",\"D\":\"Unsubscribe rate\",\"E\":\"Office attendance\"}','A, B, C, D',2,'Delivery rate, Click-through rate, Conversion rate, and Unsubscribe rate.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(434,8,NULL,NULL,NULL,'department','A high open rate alone proves that an email campaign generated business revenue.','true_false','{\"A\":\"True\",\"B\":\"False\"}','False',1,'False. High opens do not prove conversions or revenue generation.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(435,8,NULL,NULL,NULL,'department','Email marketing lists should be managed in accordance with applicable privacy, consent, and unsubscribe requirements.','true_false','{\"A\":\"True\",\"B\":\"False\"}','True',1,'True. Compliance with privacy, consent, and unsubscribe rules is legally required and preserves deliverability.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(436,8,NULL,NULL,NULL,'department','What is the difference between open rate and click-through rate?','short_answer',NULL,'Open rate estimates the proportion of delivered emails recorded as opened; click-through rate measures the proportion of delivered emails that generated clicks. Open tracking can be affected by privacy features and should be interpreted cautiously.',3,'Open rate estimates the proportion of delivered emails recorded as opened; click-through rate measures the proportion of delivered emails that generated clicks. Open tracking can be affected by privacy features and should be interpreted cautiously.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(437,8,NULL,NULL,NULL,'department','What is email personalization?','short_answer',NULL,'Adapting email content to relevant recipient information, preferences, role, or behavior.',3,'Adapting email content to relevant recipient information, preferences, role, or behavior.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(438,8,NULL,NULL,NULL,'department','What is the purpose of a call to action (CTA) in an email?','short_answer',NULL,'To encourage the recipient to take a specific next step, such as booking a meeting, visiting a webpage, or requesting a demo.',3,'To encourage the recipient to take a specific next step, such as booking a meeting, visiting a webpage, or requesting a demo.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(439,8,NULL,NULL,NULL,'department','Your email campaign has a high delivery rate but very few clicks. How would you investigate and improve performance?','scenario',NULL,'Review audience relevance, email content, CTA visibility, landing-page relevance, campaign objective, and click-through data; test improvements systematically.',5,'Review audience relevance, email content, CTA visibility, landing-page relevance, campaign objective, and click-through data; test improvements systematically.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(440,8,NULL,NULL,NULL,'department','Many emails in your campaign are bouncing. What actions would you take?','scenario',NULL,'Analyze hard and soft bounces, suppress invalid addresses, verify list quality and consent, review sending practices, and investigate technical deliverability issues.',5,'Analyze hard and soft bounces, suppress invalid addresses, verify list quality and consent, review sending practices, and investigate technical deliverability issues.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37'),(441,8,NULL,NULL,NULL,'department','You are asked to email 5,000 prospects about a new B2B service, but the list contains contacts with different roles and interests. How would you plan the campaign?','scenario',NULL,'Validate the list and permission basis, segment contacts by relevant business characteristics, tailor messaging and CTAs, test a small campaign where appropriate, and measure meaningful outcomes.',5,'Validate the list and permission basis, segment contacts by relevant business characteristics, tailor messaging and CTAs, test a small campaign where appropriate, and measure meaningful outcomes.',180,1.00,1,'2026-10-22 20:34:37','2026-10-22 20:34:37');
/*!40000 ALTER TABLE `interview_questions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `interview_recordings`
--

DROP TABLE IF EXISTS `interview_recordings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `interview_recordings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `interview_id` int(10) unsigned NOT NULL,
  `interview_answer_id` int(10) unsigned DEFAULT NULL,
  `candidate_id` int(10) unsigned NOT NULL,
  `storage_key` varchar(255) NOT NULL,
  `file_path` varchar(500) NOT NULL,
  `original_filename` varchar(255) NOT NULL,
  `mime_type` varchar(100) NOT NULL DEFAULT 'audio/webm',
  `file_size` bigint(20) unsigned NOT NULL DEFAULT 0,
  `duration_seconds` int(10) unsigned NOT NULL DEFAULT 0,
  `consent_recorded_at` datetime DEFAULT NULL,
  `uploaded_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `interview_answer_id` (`interview_answer_id`),
