DROP TABLE IF EXISTS `interviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `interviews` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` int(10) unsigned NOT NULL,
  `round_type` enum('hr','department','final') NOT NULL,
  `interviewer_id` int(10) unsigned DEFAULT NULL,
  `scheduled_at` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `status` enum('scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'scheduled',
  `total_questions` int(10) unsigned NOT NULL DEFAULT 0,
  `total_score` decimal(5,2) DEFAULT NULL,
  `maximum_score` decimal(5,2) DEFAULT NULL,
  `recommendation` enum('recommended','hold','rejected') DEFAULT NULL,
  `interviewer_summary` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `mode` varchar(20) DEFAULT 'Online',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_cand_round` (`candidate_id`,`round_type`),
  KEY `interviewer_id` (`interviewer_id`),
  KEY `idx_interview_cand` (`candidate_id`),
  KEY `idx_interview_status` (`status`),
  CONSTRAINT `interviews_ibfk_1` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `interviews_ibfk_2` FOREIGN KEY (`interviewer_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
