DROP TABLE IF EXISTS `joining_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `joining_records` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `candidate_id` int(10) unsigned NOT NULL,
  `employee_id` int(10) unsigned DEFAULT NULL,
  `joining_status` enum('pending','confirmed','completed','cancelled') NOT NULL DEFAULT 'pending',
  `proposed_joining_date` date NOT NULL,
  `confirmed_joining_date` date DEFAULT NULL,
  `assigned_department_id` int(10) unsigned NOT NULL,
  `assigned_position_id` int(10) unsigned NOT NULL,
  `reporting_manager_id` int(10) unsigned DEFAULT NULL,
  `probation_months` tinyint(3) unsigned NOT NULL DEFAULT 3,
  `offer_status` enum('draft','sent','accepted','declined') NOT NULL DEFAULT 'draft',
  `documents_verified` tinyint(1) NOT NULL DEFAULT 0,
  `checklist_status` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`checklist_status`)),
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
