INSERT INTO `positions` VALUES (1,1,'QA_ENG','QA Automation Engineer','Develop test automation suites and verify software quality.','Selenium, Playwright, Cypress, CI/CD knowledge.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(2,1,'QA_MAN','Manual Test Specialist','Functional, regression, and cross-browser testing specialist.','Strong test case design, Jira, Bugzilla experience.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(3,2,'DEV_FULLSTACK','Full Stack Developer','Design and implement Next.js, Node.js and SQL applications.','Next.js, React, Node.js, MySQL, TypeScript.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(4,2,'DEV_BACKEND','Backend Engineer','Develop scalable APIs, database queries and microservices.','Node.js, Express, MySQL, Redis, REST APIs.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(5,2,'DEV_FRONTEND','Frontend Engineer','Build modern, accessible, responsive web interfaces.','React, TypeScript, Tailwind CSS, Performance optimization.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(6,3,'PM_TECH','Technical Project Manager','Coordinate sprints, roadmap planning and technical delivery.','Scrum/Agile certification, Jira, resource planning.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(7,3,'PROD_MGR','Product Manager','Define product vision, user stories, and feature prioritization.','Product roadmapping, UX metrics, stakeholder mgmt.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(8,4,'SALES_BDE','Business Development Executive','B2B lead generation, prospect calling and client engagement.','Excellent verbal communication, CRM expertise.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(9,4,'SALES_MGR','Enterprise Sales Manager','Close enterprise contracts and oversee sales pipelines.','B2B tech sales track record, contract negotiation.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(10,5,'HR_RECRUITER','Technical Recruiter','Sourcing, screening, and coordinating recruitment rounds.','Tech talent sourcing, ATS management, behavioral interviewing.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(11,5,'HR_EXEC','HR Operations Executive','Employee onboarding, documentation, and compliance support.','Labor law knowledge, HRMS operations, onboarding.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(12,6,'OPS_SYSADMIN','System Administrator','Manage on-premise hardware, networks, and workstation security.','Linux, Windows Server, Networking, Active Directory.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(13,6,'OPS_COORD','Operations Coordinator','Facilities management and operational vendor coordination.','Vendor management, facilities oversight, procurement.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(14,7,'DBA_MYSQL','MySQL Database Administrator','Maintain high availability, query optimization, and backups.','MySQL 8+, indexing, replication, performance tuning.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(15,7,'DATA_ENG','Data Engineer','Build ETL pipelines and maintain data warehouses.','SQL, Python, ETL tools, schema normalization.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(16,8,'EMAIL_SPEC','Email Marketing Specialist','Execute email campaigns, A/B testing and monitor deliverability.','Klaviyo, Mailchimp, HTML email templating, SPF/DKIM.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(17,8,'EMAIL_STRAT','Lifecycle Campaign Strategist','Customer journeys, automated drip sequences, and retention metrics.','Audience segmentation, copywriting, analytical reporting.',1,'2026-10-09 19:30:12','2026-10-09 19:30:12'),(18,4,'DEMAND_GEN','Demand Generation Specialist','Drive B2B demand generation, inbound/outbound pipeline and ABM campaigns.','ICP definition, MQL/SQL lifecycle, BANT, ABM, Campaign tracking.',1,'2026-10-09 20:27:08','2026-10-09 20:27:08');
