INSERT INTO `screening_questions` VALUES (1,1,1,'Identify and Correct Errors','Display a sample document or dataset containing five predefined errors involving spelling, formatting, or inconsistent data. Identify each error, specify what is wrong, and provide the corrected value.','Examine the sample document below carefully. Identify all 5 errors and enter each original error alongside your corrected version in the answer table.','data_quality','hybrid',30,'{\"sample_document\":\"Taraj Global Solutins Employee Record:\\n1. Employee ID: TGS-EMP-001\\n2. Date of Joing: 2026/13/45\\n3. Department: Quality Assurannce\\n4. Contact Email: alex.smith@@tarajglobal.com\\n5. Compensation: $500,000 INR\"}','{\"errors\":[{\"error\":\"Solutins\",\"correction\":\"Solutions\",\"description\":\"Spelling error in company name\"},{\"error\":\"Joing\",\"correction\":\"Joining\",\"description\":\"Spelling error in label\"},{\"error\":\"2026/13/45\",\"correction\":\"2026-04-13 (or valid YYYY-MM-DD)\",\"description\":\"Invalid month 13 and day 45\"},{\"error\":\"Assurannce\",\"correction\":\"Assurance\",\"description\":\"Spelling error in department\"},{\"error\":\"alex.smith@@tarajglobal.com\",\"correction\":\"alex.smith@tarajglobal.com\",\"description\":\"Double @ symbol in email\"},{\"error\":\"$500,000 INR\",\"correction\":\"₹500,000 or 500,000 INR\",\"description\":\"Conflicting currency symbols ($ and INR)\"}]}','Award 6 marks per correctly identified and corrected error up to a maximum of 30 marks. Partial marks allowed if error is identified but correction has minor typo.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(2,1,2,'Data Quality Check','Analyze the 10-record dataset below. Identify each data quality issue (such as duplicates, missing fields, or invalid formats). Specify the affected record ID, affected field, and your suggested correction.','Review the records in the spreadsheet table. Spot all data discrepancies, missing fields, and duplicates. Record affected record numbers and specific fields.','data_quality','hybrid',30,'{\"records\":[{\"id\":1,\"name\":\"Aarav Sharma\",\"email\":\"aarav@tgs.com\",\"phone\":\"9876543210\",\"status\":\"Active\"},{\"id\":2,\"name\":\"Bhavna Patel\",\"email\":\"bhavna@tgs.com\",\"phone\":\"\",\"status\":\"Active\"},{\"id\":3,\"name\":\"Chirag Joshi\",\"email\":\"chirag.joshitgs.com\",\"phone\":\"9876543212\",\"status\":\"Pending\"},{\"id\":4,\"name\":\"Aarav Sharma\",\"email\":\"aarav@tgs.com\",\"phone\":\"9876543210\",\"status\":\"Active\"},{\"id\":5,\"name\":\"Divya Nair\",\"email\":\"divya@tgs.com\",\"phone\":\"9876543214\",\"status\":\"Active\"},{\"id\":6,\"name\":\"\",\"email\":\"rohit@tgs.com\",\"phone\":\"9876543215\",\"status\":\"Inactive\"},{\"id\":7,\"name\":\"Farhan Khan\",\"email\":\"farhan@tgs.com\",\"phone\":\"12345\",\"status\":\"Active\"},{\"id\":8,\"name\":\"Gita Sen\",\"email\":\"gita@tgs.com\",\"phone\":\"9876543217\",\"status\":\"UNKNOWN_VAL\"},{\"id\":9,\"name\":\"Harish Rao\",\"email\":\"harish@tgs.com\",\"phone\":\"9876543218\",\"status\":\"Active\"},{\"id\":10,\"name\":\"Isha Roy\",\"email\":\"isha@tgs.com\",\"phone\":\"9876543219\",\"status\":\"Active\"}]}','{\"issues\":[{\"record_id\":2,\"field\":\"phone\",\"issue\":\"Missing phone number\"},{\"record_id\":3,\"field\":\"email\",\"issue\":\"Invalid email syntax (missing @ symbol)\"},{\"record_id\":4,\"field\":\"all (duplicate)\",\"issue\":\"Duplicate of Record 1 (Aarav Sharma)\"},{\"record_id\":6,\"field\":\"name\",\"issue\":\"Missing candidate/employee name\"},{\"record_id\":7,\"field\":\"phone\",\"issue\":\"Invalid phone length (only 5 digits)\"},{\"record_id\":8,\"field\":\"status\",\"issue\":\"Non-standard status value UNKNOWN_VAL\"}]}','5 marks per correctly detected issue with record ID and remediation suggestion, up to 30 marks total.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(3,1,3,'Quality Improvement & Root Cause Action Plan','Scenario: A critical QA audit report containing incorrect KPI calculation data has already been shared with the department manager and client stakeholders. Write three practical steps to identify the root cause, correct the report, and prevent the issue from recurring.','Structure your response into 3 distinct operational phases: 1. Root Cause Analysis, 2. Immediate Containment & Correction, 3. Long-term Preventive Controls.','written','manual',40,'{\"scenario\":\"A shared executive report contains an error in the quarterly defect density formula, understating escaped defects by 40%.\"}','{\"expected_sections\":[\"Root Cause Analysis (5 Whys / Fishbone analysis of formula source)\",\"Immediate Correction & Transparent Stakeholder Notification\",\"Preventive Engineering (automated report validation, peer signoff, test assertions)\"]}','10 marks for systematic RCA methodology; 15 marks for transparent stakeholder communication and correction protocol; 15 marks for automated CI/regression preventative safeguards.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(4,2,1,'Debug the Code','The following JavaScript function is intended to take an array of numbers, filter out odd numbers, sum only the even numbers, and return the total. However, it contains intentional errors (loop condition, equality operator, and return statement). Correct the function so it works as expected.','Inspect the code snippet, correct the syntax and logic errors, and provide the working function.','code','automatic',30,'{\"language\":\"javascript\",\"buggy_code\":\"function sumEvenNumbers(numbers) {\\n  let sum = 0;\\n  for (let i = 0; i <= numbers.length; i++) {\\n    if (numbers[i] % 2 = 0) {\\n      sum += numbers;\\n    }\\n  }\\n  return;\\n}\",\"test_cases\":[{\"input\":[1,2,3,4,5,6],\"expected\":12},{\"input\":[2,4,8],\"expected\":14},{\"input\":[1,3,5],\"expected\":0}]}','{\"fixed_code\":\"function sumEvenNumbers(numbers) {\\n  let sum = 0;\\n  for (let i = 0; i < numbers.length; i++) {\\n    if (numbers[i] % 2 === 0) {\\n      sum += numbers[i];\\n    }\\n  }\\n  return sum;\\n}\"}','10 marks for boundary condition (i < numbers.length), 10 marks for comparison equality (=== 0), 10 marks for accumulator logic (sum += numbers[i]) and returning sum.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(5,2,2,'Build a Simple Form Component','Candidate task: Create or complete a form component containing Name, Email, and Phone fields with client-side validation requirements: 1. All fields are required; 2. Email must match a valid email format; 3. Phone must be at least 10 digits; 4. Display a success message upon valid submission.','Provide clean HTML/JS or React code fulfilling the form structure, validation handlers, and submission feedback.','code','manual',30,'{\"required_fields\":[\"name\",\"email\",\"phone\"],\"features\":[\"Required field checks\",\"Email regex validation\",\"10-digit phone check\",\"Success notification state\"]}','{\"expected_elements\":[\"Form with input fields for name, email, phone\",\"Validation functions or HTML5 validation attributes with custom state\",\"Email regex test e.g. /^[^s@]+@[^s@]+.[^s@]+$/\",\"State for error messages and success toast/alert\"]}','10 marks for clean semantic structure; 10 marks for robust input validation logic; 10 marks for state handling and success feedback.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(6,2,3,'Programming Logic: Array Statistics','Write a program/function `calculateStats(numbers)` that accepts an array of numbers and returns an object containing: the largest number (max), smallest number (min), and average (rounded to 2 decimal places). Ensure it handles positive, negative, and duplicate numbers, and returns { min: null, max: null, average: 0 } if the array is empty.','Implement the function in JavaScript/TypeScript. Consider edge cases such as empty input arrays and negative integers.','code','automatic',40,'{\"language\":\"javascript\",\"starter_code\":\"function calculateStats(numbers) {\\n  // Write your implementation here\\n  return { min: 0, max: 0, average: 0 };\\n}\",\"test_cases\":[{\"input\":[10,20,30,40],\"expected\":{\"min\":10,\"max\":40,\"average\":25}},{\"input\":[-5,0,5,10],\"expected\":{\"min\":-5,\"max\":10,\"average\":2.5}},{\"input\":[],\"expected\":{\"min\":null,\"max\":null,\"average\":0}}]}','{\"solution\":\"function calculateStats(numbers) {\\n  if (!numbers || numbers.length === 0) return { min: null, max: null, average: 0 };\\n  const min = Math.min(...numbers);\\n  const max = Math.max(...numbers);\\n  const sum = numbers.reduce((acc, val) => acc + val, 0);\\n  const average = Number((sum / numbers.length).toFixed(2));\\n  return { min, max, average };\\n}\"}','10 marks for maximum calculation; 10 marks for minimum calculation; 10 marks for average; 10 marks for empty array handling.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(7,3,1,'Task Prioritization & Impact Matrix','You have five concurrent tasks today:\n1. Critical server outage affecting 50 internal team members (Urgent, High Impact)\n2. Preparing quarterly board presentation slides due in 4 days (Non-urgent, High Impact)\n3. Replying to general vendor inquiries (Non-urgent, Low Impact)\n4. Reviewing pending candidate scorecards due by 5 PM today (Urgent, Medium Impact)\n5. Scheduling the monthly team birthday celebration (Non-urgent, Low Impact)\n\nRank these tasks from highest priority (1) to lowest (5) and explain your reasoning.','Apply the Eisenhower Impact/Urgency Matrix. Provide your ranked list (e.g. 1, 4, 2, 3, 5) and justify why high-impact tasks take precedence over low-impact administrative tasks.','prioritization','hybrid',30,'{\"tasks\":[{\"id\":1,\"text\":\"Critical server outage affecting 50 internal users\",\"urgency\":\"High\",\"impact\":\"High\"},{\"id\":2,\"text\":\"Preparing quarterly board presentation slides due in 4 days\",\"urgency\":\"Medium\",\"impact\":\"High\"},{\"id\":3,\"text\":\"Replying to general vendor inquiries\",\"urgency\":\"Low\",\"impact\":\"Low\"},{\"id\":4,\"text\":\"Reviewing pending candidate scorecards due by 5 PM today\",\"urgency\":\"High\",\"impact\":\"Medium\"},{\"id\":5,\"text\":\"Scheduling monthly team celebration for next Friday\",\"urgency\":\"Low\",\"impact\":\"Low\"}]}','{\"ideal_rank\":[1,4,2,3,5],\"acceptable_ranks\":[[1,4,2,3,5],[1,2,4,3,5]],\"rationale\":\"Task 1 is immediate operational blocker; Task 4 has a same-day deadline; Task 2 is strategic high impact; Tasks 3 and 5 are lower urgency/impact.\"}','15 marks for logical task ranking (Task 1 first, Task 5 last); 15 marks for business justification.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(8,3,2,'Team Conflict Resolution & Stakeholder Alignment','Scenario: Two key team leads disagree about a project deadline. The Lead Developer insists on delaying the release by one week to resolve non-critical UI glitches, while the Operations Manager insists on meeting the original deadline promised to the client. Describe how you would mediate this disagreement, agree on responsibilities, and protect the delivery schedule.','Detail your mediation strategy, how you assess customer impact vs technical debt, and how you document agreed-upon action items.','written','manual',30,'{\"scenario\":\"Disagreement between Lead Developer and Operations Manager regarding a major customer milestone release.\"}','{\"key_points\":[\"Private mediation to understand root concerns\",\"Risk assessment: categorizing glitches into critical vs cosmetic\",\"Compromise: on-time release of core features with Day 3 patch for minor UI items\",\"Written RACI agreement & transparent communication with client\"]}','10 marks for constructive dispute mediation; 10 marks for pragmatic customer-centric compromise; 10 marks for follow-through accountability.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(9,3,3,'5-Day Project Sprint Planning','Scenario: Your team must complete and roll out a new internal document management workflow within exactly five working days. Create a structured 5-day project plan that includes: specific tasks per day, owners/responsibilities, daily deadlines, and progress checkpoints/milestones.','Provide a structured day-by-day roadmap (Day 1 through Day 5) detailing deliverables, owner roles, and review gates.','written','manual',40,'{\"scope\":\"5-day sprint for internal document management workflow rollout.\"}','{\"expected_plan\":[\"Day 1: Requirement freeze, stakeholder signoff, role assignments (Owner: PM)\",\"Day 2: Architecture & workflow configuration (Owner: Tech Lead)\",\"Day 3: Core execution & document ingestion testing (Owner: Dev/Ops)\",\"Day 4: User acceptance testing (UAT) & feedback loops (Owner: QA/Users)\",\"Day 5: Training documentation, final executive sign-off, live rollout (Owner: PM & Leads)\"]}','10 marks for realistic sequencing; 10 marks for clear role ownership; 10 marks for milestone checkpoints; 10 marks for contingency planning.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(10,4,1,'Write a B2B Sales Outreach Email','Scenario: You are introducing Taraj Global Solutions recruitment and screening services to the Head of Talent Acquisition at a fast-growing IT services company. Write a concise, compelling cold outreach email with: 1. Subject Line, 2. Value Proposition addressing recruitment bottlenecks, 3. Low-friction Call to Action (CTA) requesting a brief 15-minute call.','Keep the email professional, customer-focused, under 200 words, and free of pushy jargon.','written','manual',30,'{\"target_persona\":\"Head of Talent Acquisition at 300-employee IT firm.\"}','{\"criteria\":[\"Subject line: Clear, personalized, curiosity-inducing (<50 chars)\",\"Value proposition: Quantifiable benefit (e.g. 50% faster screening, verified candidate pipelines)\",\"CTA: Low commitment (e.g. \\\"Do you have 15 minutes this Thursday morning?\\\")\"]}','10 marks for subject line effectiveness; 10 marks for value proposition relevance; 10 marks for clear call to action.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(11,4,2,'Handle a Customer Pricing Objection','Scenario: A high-potential enterprise prospect says: \"Your recruitment and screening platform looks good, but your quote is 25% higher than what another agency is offering us.\" Write a professional response that acknowledges the objection, reframes value around candidate retention and ROI, and avoids unapproved discounts.','Respond with empathy, communicate differentiation without criticizing the competitor, and transition to a demonstration of ROI.','written','manual',30,'{\"objection\":\"Your service is 25% higher than the market competitor.\"}','{\"talking_points\":[\"Acknowledge pricing sensitivity respectfully\",\"Highlight total cost of hire vs bad hire replacement cost\",\"Reinforce unique advantages (rigorous department screening, 90-day replacement guarantee)\",\"Propose an ROI breakdown or pilot cohort\"]}','10 marks for empathetic objection handling; 10 marks for value/ROI justification; 10 marks for closing professionalism.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(12,4,3,'Sales Performance Metric Calculations','Scenario:\n- Total Prospects Contacted: 100\n- Positive Responses Received: 20\n- Qualified Meetings Booked: 5\n\nCalculate:\n1. Positive Response Rate = (Positive Responses / Prospects Contacted) × 100\n2. Meeting Booking Rate = (Meetings Booked / Prospects Contacted) × 100\n\nEnter your final numeric percentages and formulas.','Enter the exact numeric percentage for Positive Response Rate and Meeting Booking Rate.','calculation','automatic',40,'{\"prospects_contacted\":100,\"positive_responses\":20,\"meetings_booked\":5}','{\"positive_response_rate\":20,\"meeting_booking_rate\":5,\"formula_1\":\"20 / 100 * 100 = 20%\",\"formula_2\":\"5 / 100 * 100 = 5%\"}','20 marks for Positive Response Rate = 20%; 20 marks for Meeting Booking Rate = 5%. Partial marks for correct formula with minor arithmetic mistake.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(13,5,1,'Candidate Resume Screening & Match Analysis','Job Requirement: Mid-Level Full Stack Developer requiring 3+ years experience in React, Node.js, and SQL database design.\n\nCandidate Profile A: 3.5 years experience in React and Node.js; built REST APIs with MySQL; notice period: 15 days.\nCandidate Profile B: 5 years experience in Java and Angular; completed a 3-month certification in Node.js; notice period: 60 days.\n\nSelect the better candidate match and justify your choice using objective, job-relevant criteria.','State your selected candidate (Profile A or Profile B) and provide 3 job-related reasons addressing tech stack fit, immediate onboarding lead time, and project risk.','written','manual',30,'{\"requirement\":\"Full Stack Developer with React, Node.js, and SQL (3+ years experience)\",\"profile_a\":\"3.5 yrs React/Node.js/MySQL, 15 days notice\",\"profile_b\":\"5 yrs Java/Angular, 3-mo Node.js course, 60 days notice\"}','{\"selected_candidate\":\"Candidate Profile A\",\"reasons\":[\"Direct hands-on experience with required core stack (React, Node.js, MySQL)\",\"Notice period is 15 days vs 60 days for Profile B, enabling immediate project continuity\",\"Profile B requires significant ramp-up from Java/Angular\"]}','15 marks for selecting Candidate A; 15 marks for coherent, evidence-based reasoning.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(14,5,2,'Interview Scheduling & Calendar Optimization','Three applicants need 1-hour interview slots on Friday morning:\n- Candidate 1 is available 10:00 AM - 11:00 AM\n- Candidate 2 is available 09:00 AM - 11:00 AM\n- Candidate 3 is available 11:00 AM - 12:00 PM\nInterviewers:\n- Interviewer A (HR Lead) is available 09:00 AM - 11:00 AM\n- Interviewer B (Technical Lead) is available 10:00 AM - 12:00 PM\n\nCreate a conflict-free schedule matching each candidate with an available interviewer and time slot.','Present the schedule for each candidate: Candidate Name -> Time Slot -> Assigned Interviewer without overlapping appointments.','scheduling','hybrid',30,'{\"candidates\":[{\"name\":\"Candidate 1\",\"window\":\"10:00 AM - 11:00 AM\"},{\"name\":\"Candidate 2\",\"window\":\"09:00 AM - 11:00 AM\"},{\"name\":\"Candidate 3\",\"window\":\"11:00 AM - 12:00 PM\"}],\"interviewers\":[{\"name\":\"Interviewer A\",\"window\":\"09:00 AM - 11:00 AM\"},{\"name\":\"Interviewer B\",\"window\":\"10:00 AM - 12:00 PM\"}]}','{\"valid_schedule\":[{\"candidate\":\"Candidate 2\",\"time\":\"09:00 AM - 10:00 AM\",\"interviewer\":\"Interviewer A\"},{\"candidate\":\"Candidate 1\",\"time\":\"10:00 AM - 11:00 AM\",\"interviewer\":\"Interviewer B (or A)\"},{\"candidate\":\"Candidate 3\",\"time\":\"11:00 AM - 12:00 PM\",\"interviewer\":\"Interviewer B\"}]}','10 marks per valid, non-conflicting pairing up to 30 marks total. Automatically validated against availability windows.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(15,5,3,'Draft Formal Interview Invitation Email','Draft a professional interview invitation email to candidate \"Rohit Mehra\" for a Round 2 Technical Assessment for the \"Senior Software Engineer\" position. The interview is scheduled for Tuesday, 10:30 AM IST via Google Meet. Include: role title, interview agenda, technical preparation instructions, duration (45 mins), and recruiter contact info.','Ensure professional tone, complete details, clear instructions, and formal company signoff.','written','manual',40,'{\"candidate_name\":\"Rohit Mehra\",\"position\":\"Senior Software Engineer\",\"date_time\":\"Tuesday, 10:30 AM IST\",\"platform\":\"Google Meet\",\"duration\":\"45 minutes\"}','{\"checklist\":[\"Warm greeting & clear statement of interview round\",\"Specific date, time, and timezone\",\"Platform link / meeting details\",\"Preparation guidelines (laptop, quiet environment, code sample)\",\"Recruiter contact for questions or rescheduling\"]}','10 marks for completeness of details; 10 marks for clear technical instructions; 10 marks for professional tone; 10 marks for formatting.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(16,6,1,'Work Queue Prioritization','Arrange the following five operational tasks in the order they should be executed (1 = highest priority to 5 = lowest priority) and explain your reasoning:\n1. Server cooling anomaly warning in Data Center Room B (Urgent, Critical Asset)\n2. Processing monthly stationery vendor invoices due in 10 days (Non-urgent, Low Impact)\n3. Restocking safety protective gear for night shift workers due at 7 PM (Urgent, High Safety Impact)\n4. Archiving completed procurement records from last quarter (Non-urgent, Low Impact)\n5. Investigating a shipment delay inquiry from a top enterprise client (High Urgency, High Commercial Impact)','Provide your ranking (e.g. 1, 3, 5, 2, 4) and provide the operational reasoning for safety, client SLA, and asset protection.','prioritization','hybrid',30,'{\"tasks\":[{\"id\":1,\"text\":\"Server cooling anomaly in Data Center\",\"type\":\"Asset/Uptime Risk\"},{\"id\":2,\"text\":\"Processing stationery invoices due in 10 days\",\"type\":\"Administrative\"},{\"id\":3,\"text\":\"Restocking safety protective gear before 7 PM shift\",\"type\":\"Human Safety\"},{\"id\":4,\"text\":\"Archiving last quarter procurement records\",\"type\":\"Routine Archive\"},{\"id\":5,\"text\":\"Shipment delay inquiry from top enterprise client\",\"type\":\"Client SLA\"}]}','{\"ideal_order\":[3,1,5,2,4],\"acceptable_orders\":[[3,1,5,2,4],[1,3,5,2,4]],\"rationale\":\"Personnel safety (Task 3) and infrastructure failure prevention (Task 1) take utmost precedence, followed immediately by client SLA resolution (Task 5).\"}','15 marks for logical ranking; 15 marks for operational risk and safety reasoning.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(17,6,2,'Inventory Stock Balance Calculation','Scenario:\n- Starting Warehouse Stock: 250 units\n- Incoming Supplier Deliveries: 80 units\n- Outgoing Dispatched Shipments: 135 units\n\nCalculate the remaining stock balance. Provide the final numeric answer and your step-by-step arithmetic equation.','Enter the remaining stock number and formula (e.g. Starting + Incoming - Outgoing).','calculation','automatic',30,'{\"starting_stock\":250,\"incoming_stock\":80,\"outgoing_stock\":135}','{\"remaining_stock\":195,\"equation\":\"250 + 80 - 135 = 195\"}','30 marks for correct numeric calculation (195 units). Partial credit of 15 marks if formula is correct but arithmetic is flawed.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(18,6,3,'Process Delay & Bottleneck Resolution','Scenario: Daily operations handover reports are consistently delayed by 60 to 90 minutes because the third-party dispatch logistics provider submits manifest counts late. Identify two plausible root causes for this recurring bottleneck and propose two actionable operational solutions (e.g. automated API ingestion, cutoff penalties, buffer windows).','Detail 2 root causes and 2 concrete operational remedies with measurable outcomes.','written','manual',40,'{\"problem\":\"Handover reports delayed 60-90 minutes daily due to third-party manifest delays.\"}','{\"root_causes\":[\"Manual paper-based manifest handover\",\"Lack of enforceable SLA with external vendor\"],\"solutions\":[\"Automated EDI/API digital manifest integration\",\"Strict contractual cutoff with phased dispatch staging\"]}','10 marks per root cause (20 marks); 10 marks per practical operational solution (20 marks).',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(19,7,1,'Filter Employees by Department','Given the `assessment_employees` table with columns (`id`, `name`, `department`, `salary`), write an SQL query that displays all employees belonging to the \"Sales\" department.','Write the complete SQL SELECT statement. Queries will be validated against the assessment sample database.','sql','automatic',30,'{\"table_name\":\"assessment_employees\",\"schema\":\"id INT, name VARCHAR(100), department VARCHAR(50), salary DECIMAL(10,2)\",\"sample_rows\":[{\"id\":1,\"name\":\"Aarav Sharma\",\"department\":\"Sales\",\"salary\":35000},{\"id\":2,\"name\":\"Priya Patel\",\"department\":\"Development\",\"salary\":55000},{\"id\":3,\"name\":\"Rohan Verma\",\"department\":\"Sales\",\"salary\":42000}]}','{\"expected_sql\":\"SELECT * FROM assessment_employees WHERE department = \'Sales\';\",\"accepted_patterns\":[{},{}]}','30 marks for syntactically correct and logically accurate SQL filtering on department = \"Sales\".',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(20,7,2,'Find Duplicate Email Addresses','Given the `assessment_customers` table with columns (`id`, `name`, `email`), write an SQL query that identifies all email addresses appearing more than once, along with the count of occurrences.','Use aggregate functions and group filtering to isolate duplicate entries.','sql','automatic',30,'{\"table_name\":\"assessment_customers\",\"schema\":\"id INT, name VARCHAR(100), email VARCHAR(150)\",\"sample_rows\":[{\"id\":1,\"name\":\"Customer One\",\"email\":\"contact@clienta.com\"},{\"id\":2,\"name\":\"Customer Two\",\"email\":\"sales@clientb.com\"},{\"id\":3,\"name\":\"Customer Three\",\"email\":\"contact@clienta.com\"}]}','{\"expected_sql\":\"SELECT email, COUNT(*) AS occurrences FROM assessment_customers GROUP BY email HAVING COUNT(*) > 1;\",\"accepted_patterns\":[{}]}','30 marks for correct GROUP BY email and HAVING COUNT(*) > 1 clause.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(21,7,3,'Filter and Sort High-Earning Employees','Given the `assessment_employees` table with columns (`id`, `name`, `department`, `salary`), write an SQL query that displays all employees earning a salary greater than 30000, sorted from highest salary to lowest.','Write the query utilizing a WHERE predicate and descending sort order.','sql','automatic',40,'{\"table_name\":\"assessment_employees\",\"condition\":\"salary > 30000\",\"order\":\"salary DESC\"}','{\"expected_sql\":\"SELECT * FROM assessment_employees WHERE salary > 30000 ORDER BY salary DESC;\",\"accepted_patterns\":[{}]}','20 marks for correct filtering condition (salary > 30000); 20 marks for descending ordering clause (ORDER BY salary DESC).',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(22,8,1,'Create a B2B Email Marketing Campaign','Write a cold outbound email promoting Taraj Global Solutions recruitment intelligence software to HR Directors at high-growth startups. Include:\n1. Subject Line (compelling, high open rate potential)\n2. Email Body (hook, addressing hiring delays, solution overview, social proof)\n3. Clear Call-to-Action (CTA).','Ensure professional copy, good readability, and clear value proposition.','written','manual',30,'{\"target_audience\":\"HR Directors & Talent Heads at high-growth companies\"}','{\"criteria\":[\"Engaging, non-spammy subject line\",\"Specific problem addressed (time spent manually screening resumes)\",\"Clear benefit (multi-round automated screening, verified rankings)\",\"Low-friction CTA (e.g. 5-minute interactive preview)\"]}','10 marks for subject line; 10 marks for body value proposition; 10 marks for call to action.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(23,8,2,'Calculate Email Campaign Performance Metrics','Campaign Performance Data:\n- Emails Sent: 1,000\n- Emails Delivered: 900\n- Unique Opens: 180\n- Unique Clicks: 45\n\nCalculate:\n1. Delivery Rate (%) = (Delivered / Sent) × 100\n2. Open Rate (%) = (Opens / Delivered) × 100\n3. Click-Through Rate (CTR) (%) = (Clicks / Delivered) × 100\n\nEnter the exact numeric percentage values.','For this assessment, use delivered emails as the denominator for both open rate and CTR. Enter numeric values for all three rates.','calculation','automatic',30,'{\"sent\":1000,\"delivered\":900,\"opens\":180,\"clicks\":45}','{\"delivery_rate\":90,\"open_rate\":20,\"click_through_rate\":5,\"formulas\":[\"Delivery Rate: 900 / 1000 * 100 = 90%\",\"Open Rate: 180 / 900 * 100 = 20%\",\"CTR: 45 / 900 * 100 = 5%\"]}','10 marks for Delivery Rate (90%); 10 marks for Open Rate (20%); 10 marks for Click-Through Rate (5%). Automatically checked.',1,'2026-10-13 13:58:48','2026-10-13 13:58:48'),(24,8,3,'Email Campaign Optimization & CTR Diagnosis','Scenario: An outbound marketing campaign achieved an impressive Open Rate of 36%, but a disappointing Click-Through Rate (CTR) of only 0.9%. Identify two probable root causes for this drop-off and recommend two specific, actionable improvements to increase CTR in the next iteration.','Address message-to-subject alignment, visual hierarchy, CTA placement, and landing page friction.','written','manual',40,'{\"metrics\":\"Open Rate: 36%, Click-Through Rate: 0.9%\"}','{\"causes\":[\"Misleading or clickbait subject line creating false expectation\",\"Too many competing links or buried call-to-action button\",\"Body copy too long or generic with weak value proposition\"],\"solutions\":[\"Single primary call-to-action above the fold\",\"Direct alignment between subject line promise and first sentence\",\"Concise bullet points highlighting concrete takeaways\"]}','10 marks per plausible root cause (20 marks); 10 marks per actionable optimization tactic (20 marks).',1,'2026-10-13 13:58:48','2026-10-13 13:58:48');
/*!40000 ALTER TABLE `screening_questions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(60) NOT NULL,
  `email` varchar(120) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
